importScripts("cookie-core.js", "integrity-guard.js", "protect.js");

const EXTENSION_VERSION =
  (typeof chrome !== "undefined" &&
    chrome.runtime?.getManifest &&
    chrome.runtime.getManifest()?.version) ||
  "1.0.1";
const DEFAULT_PORTAL_URL = "https://flow.doverz.com";
const ALARM_NAME = "FLOWBRIDGE_COOKIE_SYNC";
const PROTECT_ALARM_NAME = "FLOWBRIDGE_EXT_PROTECT";
/** Light sync polling — only when connected; backs off after 409. */
const SYNC_INTERVAL_MINUTES = 3;
/** Cookie lease: keep Flow signed in while connected. Alarm refreshes every few minutes. */
const FLOW_COOKIE_LEASE_SECONDS = 45 * 60;
const SESSION_COOKIE_NAME = "flowdoverz_sid";
const HEALTH_REPORT_MIN_MS = 10 * 60 * 1000;
const TAMPER_SYNC_COOLDOWN_MS = 30 * 60 * 1000;
const REMOVE_CONFLICT_MESSAGE = "Remove Modified or cookies extractor extensions.";
const SELF_CHANGED_MESSAGE =
  "This extension was changed. Reinstall the official FlowDoverz build from your dashboard.";
const UPDATE_REQUIRED_MESSAGE =
  "A new FlowDoverz extension is required. Download it from your dashboard and install it to continue.";

let syncInFlight = null;
let lastTabSyncAt = 0;
let lastHealthReportAt = 0;
let lastPortalStatusJson = "";
let lastTamperBlockAt = 0;
const flowTabReloadAt = new Map();
/** Cookie values stay in memory only — never persist them to storage (inspectable / dumpable). */
let injectedCookieCache = [];
let ownCookieMutationDepth = 0;
let theftHandling = false;

const ALLOWED_RUNTIME_ACTIONS = new Set([
  "FLOWBRIDGE_WATCHDOG_PING",
  "PORTAL_AUTH_DETECTED",
  "TRIGGER_SYNC",
  "SWITCH_COOKIE_SLOT",
  "SET_PORTAL_URL",
  "CLEAR_ON_EXPIRY",
  "TRY_UNLOCK_OFFICIAL",
  "CHECK_SECURITY",
  "OPEN_DASHBOARD",
  "OPEN_EXTENSIONS_PAGE",
  "GET_PORTAL_STATUS",
]);

function withOwnCookieMutation(fn) {
  ownCookieMutationDepth += 1;
  const done = Promise.resolve().then(fn);
  return done.finally(() => {
    setTimeout(() => {
      ownCookieMutationDepth = Math.max(0, ownCookieMutationDepth - 1);
    }, 800);
  });
}

async function writeFlowCookiesWithLease(cookies, injectToken = "") {
  if (!Array.isArray(cookies) || cookies.length === 0) return 0;
  if (!CookieCore.isInjectGateArmed(injectToken)) {
    throw new Error("Cookie protection gate is closed.");
  }

  const leaseExpiration = Math.floor(Date.now() / 1000) + FLOW_COOKIE_LEASE_SECONDS;
  return withOwnCookieMutation(async () => {
  const results = await Promise.all(
    cookies.map(async (cookie) => {
      try {
        const { details } = CookieCore.buildSetDetails(cookie);
        details.expirationDate = leaseExpiration;
        await chrome.cookies.set(details);
        return 1;
      } catch (error) {
        console.debug("Cookie lease refresh:", cookie.name, error);
        return 0;
      }
    })
  );
  return results.reduce((sum, n) => n + sum, 0);
  });
}

async function cacheInjectedCookies(cookies) {
  injectedCookieCache = Array.isArray(cookies) ? cookies.slice() : [];
  await chrome.storage.local.remove(["lastInjectedCookies"]);
  await chrome.storage.local.set({ lastInjectedAt: Date.now() });
}

async function applyCachedCookiesOnFlowOpen(tabId) {
  const found = await forceDisableConflictExtensions();
  if ((found.listedOk && found.clones.length > 0) || found.cookieTools.length > 0) {
    await applyLocalSecurityBlock(REMOVE_CONFLICT_MESSAGE);
    return;
  }

  const state = await chrome.storage.local.get(["status", "expiryAt"]);
  if (state.status !== "connected") return;
  if (state.expiryAt) {
    const expiryMs = Date.parse(state.expiryAt);
    if (!Number.isNaN(expiryMs) && Date.now() >= expiryMs) {
      await handleLogoutOrError("expired", "Your plan has expired.");
      return;
    }
  }
  const cookies = injectedCookieCache;
  if (!Array.isArray(cookies) || cookies.length === 0) {
    void performCookieSync("", { force: true });
    return;
  }

  const hadAuth = await CookieCore.hasGoogleAuthCookies();
  const sidMatches = await CookieCore.injectedSidMatches(cookies);
  try {
    let injectToken = "";
    if (!CookieCore.isInjectGateArmed()) {
      const armed = await FlowDoverzProtect.enforce();
      if (!armed.ok) return;
      injectToken = armed.token;
    }
    await withOwnCookieMutation(() => CookieCore.clearBeforeInject(cookies, injectToken));
    const written = await writeFlowCookiesWithLease(cookies, injectToken);
    if (written > 0 && tabId && (!hadAuth || !sidMatches)) {
      const last = flowTabReloadAt.get(tabId) || 0;
      if (Date.now() - last > 8000) {
        flowTabReloadAt.set(tabId, Date.now());
        await chrome.tabs.reload(tabId).catch(() => {});
      }
    }
  } catch (_error) {}
}

function cleanBaseUrl(url) {
  if (!url) return "";
  let clean = url.trim().replace(/\/+$/, "");
  clean = clean.replace(/\/+(login|signup|dashboard)\/?$/i, "");
  clean = clean.replace(/\/+[a-zA-Z0-9_-]+\.php$/i, "");
  return clean.replace(/\/+$/, "");
}

async function hasPortalLoginCookie(baseUrl) {
  try {
    const root = baseUrl.startsWith("http") ? baseUrl : `http://${baseUrl}`;
    const cookieUrl = root.endsWith("/") ? root : `${root}/`;
    const cookie = await chrome.cookies.get({ url: cookieUrl, name: SESSION_COOKIE_NAME });
    return Boolean(cookie?.value && cookie.value !== "admin-local");
  } catch (_error) {
    return false;
  }
}

/** Find the website the user is signed into (needed on mobile / custom domains). */
async function resolvePortalBaseUrl(preferred = "") {
  const preferredClean = cleanBaseUrl(preferred);
  if (preferredClean && (await hasPortalLoginCookie(preferredClean))) {
    return preferredClean;
  }

  try {
    const cookies = await chrome.cookies.getAll({ name: SESSION_COOKIE_NAME });
    for (const cookie of cookies || []) {
      if (!cookie?.value || cookie.value === "admin-local") continue;
      const host = String(cookie.domain || "").replace(/^\./, "");
      if (!host) continue;
      const candidates = [];
      if (cookie.secure) candidates.push(`https://${host}`);
      candidates.push(`http://${host}`);
      if (!host.startsWith("www.")) {
        if (cookie.secure) candidates.push(`https://www.${host}`);
        candidates.push(`http://www.${host}`);
      }
      for (const candidate of candidates) {
        try {
          const hit = await chrome.cookies.get({
            url: `${candidate}/`,
            name: SESSION_COOKIE_NAME,
          });
          if (hit?.value && hit.value !== "admin-local") {
            const resolved = cleanBaseUrl(candidate);
            await chrome.storage.local.set({ portalUrl: resolved });
            return resolved;
          }
        } catch (_error) {}
      }
    }
  } catch (_error) {}

  try {
    const tabs = await chrome.tabs.query({ active: true, currentWindow: true });
    const tabUrl = tabs?.[0]?.url || "";
    if (/^https?:\/\//i.test(tabUrl) && !/labs\.google|google\.com/i.test(tabUrl)) {
      const origin = cleanBaseUrl(new URL(tabUrl).origin);
      if (origin && (await hasPortalLoginCookie(origin))) {
        await chrome.storage.local.set({ portalUrl: origin });
        return origin;
      }
    }
  } catch (_error) {}

  return preferredClean || DEFAULT_PORTAL_URL;
}

async function updateState(status, message, extra = {}) {
  await chrome.storage.local.set({
    status,
    statusMessage: message,
    ...extra,
  });
}

async function queryGoogleFlowTabs() {
  try {
    return await chrome.tabs.query({
      url: ["*://labs.google/*", "*://*.labs.google/*"],
    });
  } catch (_error) {
    return [];
  }
}

/** Tell open Flow tabs to sign out immediately (no page refresh required). */
async function forceFlowLogoutOnTabs() {
  const tabs = await queryGoogleFlowTabs();
  await Promise.all(
    tabs.map((tab) =>
      tab.id
        ? chrome.tabs
            .sendMessage(tab.id, { action: "FLOWBRIDGE_FORCE_LOGOUT" })
            .catch(() => {})
        : Promise.resolve()
    )
  );
}

async function reloadGoogleFlowTabs() {
  const tabs = await queryGoogleFlowTabs();
  await Promise.all(
    tabs.map((tab) => (tab.id ? chrome.tabs.reload(tab.id).catch(() => {}) : Promise.resolve()))
  );
}

/** Wipe Flow cookies + force in-page logout (plan expiry / disconnect / reject). */
async function handleLogoutOrError(status, message) {
  try {
    CookieCore.disarmInjectGate();
  } catch (_error) {}
  injectedCookieCache = [];
  try {
    await withOwnCookieMutation(async () => {
      await CookieCore.clearSessionCookies();
      await CookieCore.clearCookiesForDomains(["labs.google"]);
    });
  } catch (_error) {}
  await chrome.storage.local.remove(["lastCookieHash", "activeSid", "expiryAt", "lastInjectedCookies", "lastInjectedAt"]);
  await updateState(status, message, {
    injectedCount: 0,
    daysRemaining: 0,
    expiryAt: "",
    protectionOk: false,
  });
  await forceFlowLogoutOnTabs();
  await reloadGoogleFlowTabs();
}

async function checkLocalExpiry() {
  const storage = await chrome.storage.local.get(["expiryAt", "status"]);
  if (storage.status !== "connected") return;
  if (!storage.expiryAt) return;
  const expiryMs = Date.parse(storage.expiryAt);
  if (Number.isNaN(expiryMs) || Date.now() < expiryMs) return;
  await handleLogoutOrError("expired", "Your plan has expired.");
}

function versionCompare(v1, v2) {
  const p1 = (v1 || "").split(".").map(Number);
  const p2 = (v2 || "").split(".").map(Number);
  for (let i = 0; i < Math.max(p1.length, p2.length); i++) {
    const val1 = p1[i] || 0;
    const val2 = p2[i] || 0;
    if (val1 > val2) return 1;
    if (val1 < val2) return -1;
  }
  return 0;
}

function setupAlarm() {
  chrome.alarms.create(ALARM_NAME, { periodInMinutes: SYNC_INTERVAL_MINUTES });
  chrome.alarms.create(PROTECT_ALARM_NAME, { periodInMinutes: 1 });
}

async function performCookieSync(requestedSlot = "", options = {}) {
  const force = Boolean(options && options.force);
  if (!force) {
    const state = await chrome.storage.local.get(["status", "lastTamperBlockAt"]);
    const blockedAt = Number(state.lastTamperBlockAt || lastTamperBlockAt || 0);
    if (blockedAt && Date.now() - blockedAt < TAMPER_SYNC_COOLDOWN_MS) {
      return { success: false, status: state.status || "security_blocked", skipped: true };
    }
  }
  if (syncInFlight) {
    const inFlight = syncInFlight;
    if (!force && !requestedSlot) return inFlight;
    await inFlight;
  }
  syncInFlight = runCookieSync(requestedSlot).finally(() => {
    syncInFlight = null;
  });
  return syncInFlight;
}

async function verifyGoogleCookieHealth(activeSlot, baseUrl) {
  if (!activeSlot || !baseUrl) return;
  const nowMs = Date.now();
  if (nowMs - lastHealthReportAt < HEALTH_REPORT_MIN_MS) return;
  try {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 4000);
    const resp = await fetch("https://labs.google/fx/api/user", {
      method: "GET",
      credentials: "include",
      signal: controller.signal,
    }).catch(() => null);
    clearTimeout(timeoutId);
    if (!resp) return;
    lastHealthReportAt = nowMs;
    const healthStatus = resp.ok && resp.status === 200 ? "live" : "dead";
    const reportUrl = `${baseUrl}/api/sync?reported_slot=${encodeURIComponent(activeSlot)}&reported_health=${healthStatus}`;
    fetch(reportUrl, { method: "GET", credentials: "include" }).catch(() => {});
  } catch (_error) {}
}

function isTamperResponse(status, data) {
  if (isUpdateRequiredResponse(status, data)) return false;
  if (status === 409) return true;
  const code = String(data?.code || "");
  return code === "EXTENSION_TAMPERED" || code === "EXTENSION_MODIFIED";
}

function isUpdateRequiredResponse(status, data) {
  const code = String(data?.code || "");
  return code === "EXTENSION_UPDATE_REQUIRED" || (status === 403 && code === "EXTENSION_UPDATE_REQUIRED");
}

async function applyUpdateRequiredBlock(serverMessage, latestVersion) {
  const message = String(serverMessage || "").trim() || UPDATE_REQUIRED_MESSAGE;
  const version = String(latestVersion || "").trim();
  const prev = await chrome.storage.local.get(["status", "updateRequired"]);
  const alreadyBlocked = prev.status === "security_blocked" && prev.updateRequired === true;
  lastTamperBlockAt = Date.now();
  await chrome.storage.local.set({ lastTamperBlockAt });
  try {
    CookieCore.disarmInjectGate();
  } catch (_error) {}
  injectedCookieCache = [];
  try {
    await withOwnCookieMutation(async () => {
      await CookieCore.clearSessionCookies();
      await CookieCore.clearCookiesForDomains(["labs.google"]);
    });
  } catch (_error) {}
  await chrome.storage.local.remove([
    "lastCookieHash",
    "activeSid",
    "expiryAt",
    "lastInjectedCookies",
    "lastInjectedAt",
  ]);
  await updateState("security_blocked", message, {
    injectedCount: 0,
    daysRemaining: 0,
    expiryAt: "",
    protectionOk: false,
    updateRequired: true,
    updateAvailable: true,
    serverVersion: version,
    securityReason: "update_required",
    securityDetail: `update:${version || Date.now()}`,
    serverTamperMessage: message,
  });
  if (!alreadyBlocked) {
    await forceFlowLogoutOnTabs();
    await reloadGoogleFlowTabs();
  }
  void pushPortalStatusToTabs();
  return { success: false, status: "security_blocked" };
}

async function applyServerTamperBlock(portalUrl, serverMessage) {
  let message = String(serverMessage || "").trim();
  if (!message) {
    const policy = await FlowDoverzGuard.fetchServerPolicy(portalUrl);
    message = policy?.tamperMessage || "";
  }
  const prev = await chrome.storage.local.get(["status", "statusMessage"]);
  const alreadyBlocked = prev.status === "security_blocked";
  lastTamperBlockAt = Date.now();
  await chrome.storage.local.set({ lastTamperBlockAt });
  // Website banner is Chrome-bridge only — do not write Firestore on every fail.
  // Guard.block skips tab reloads when already blocked (stops Flow blink loop).
  await FlowDoverzGuard.block(message);
  if (!alreadyBlocked) {
    await forceFlowLogoutOnTabs();
    await reloadGoogleFlowTabs();
  }
  void pushPortalStatusToTabs();
  return { success: false, status: "security_blocked" };
}

/** Local lock only — no /api/extension/tamper (avoids multi-user server write storms). */
async function applyLocalSecurityBlock(message) {
  const text = String(message || "").trim() || REMOVE_CONFLICT_MESSAGE;
  const prev = await chrome.storage.local.get(["status"]);
  const alreadyBlocked = prev.status === "security_blocked";
  lastTamperBlockAt = Date.now();
  await chrome.storage.local.set({ lastTamperBlockAt });
  await FlowDoverzGuard.block(text);
  if (!alreadyBlocked) {
    await forceFlowLogoutOnTabs();
    await reloadGoogleFlowTabs();
  }
  void pushPortalStatusToTabs();
  return { success: false, status: "security_blocked" };
}

async function runCookieSync(requestedSlot = "") {
  await checkLocalExpiry();

  const early = await chrome.storage.local.get(["portalUrl", "status"]);
  const portalGuess = await resolvePortalBaseUrl(early.portalUrl || DEFAULT_PORTAL_URL);

  // Keep modified / cookie extractors off while official is running.
  const found = await forceDisableConflictExtensions();
  if ((found.listedOk && found.clones.length > 0) || found.cookieTools.length > 0) {
    return applyLocalSecurityBlock(REMOVE_CONFLICT_MESSAGE);
  }
  if (await isSelfPackageChanged()) {
    return applyLocalSecurityBlock(SELF_CHANGED_MESSAGE);
  }

  // No portal login → stay local. Do not hit integrity/sync APIs on a timer.
  const hasSessionEarly = await hasPortalLoginCookie(portalGuess);
  if (!hasSessionEarly && !requestedSlot) {
    if (early.status === "connected" || early.status === "security_blocked") {
      await withOwnCookieMutation(() => CookieCore.clearCookiesForDomains(["labs.google"]));
      await updateState("disconnected", "Sign in on FlowDoverz login page first.", {
        lastCookieHash: "",
        injectedCount: 0,
      });
    }
    return {
      success: false,
      status: "disconnected",
      message: "Open FlowDoverz in this browser, sign in, then tap Sync now.",
    };
  }

  // Integrity FIRST — error text comes from the server policy endpoint.
  const guard = await FlowDoverzGuard.verifyWithServer(portalGuess);
  if (!guard.ok) {
    if (guard.code === "EXTENSION_UPDATE_REQUIRED") {
      return applyUpdateRequiredBlock(guard.message, guard.latestVersion);
    }
    return applyServerTamperBlock(portalGuess, guard.message);
  }

  const protection = await FlowDoverzProtect.enforce();
  if (!protection.ok) {
    return applyServerTamperBlock(portalGuess, protection.message);
  }

  const prev = await chrome.storage.local.get(["status"]);
  if (prev.status === "expired") {
    return { success: false, status: "expired" };
  }
  // Recover from a prior false block once integrity + protect pass again.
  if (prev.status === "security_blocked") {
    await chrome.storage.local.set({
      status: "disconnected",
      statusMessage: "",
      protectionOk: true,
      protectionCheckedAt: Date.now(),
      updateRequired: false,
      updateAvailable: false,
      securityReason: "",
      securityDetail: "",
    });
  }

  const storage = await chrome.storage.local.get([
    "portalUrl",
    "lastCookieHash",
    "manualRequestedSlot",
    "activeSlot",
  ]);
  let baseUrl = await resolvePortalBaseUrl(storage.portalUrl || portalGuess || DEFAULT_PORTAL_URL);

  const targetSlot =
    requestedSlot || storage.manualRequestedSlot || storage.activeSlot || "C1";
  if (requestedSlot) {
    await chrome.storage.local.set({
      manualRequestedSlot: requestedSlot,
      activeSlot: requestedSlot,
      lastCookieHash: "",
    });
    storage.lastCookieHash = "";
  }

  const hasSession = await hasPortalLoginCookie(baseUrl);
  if (!hasSession) {
    await withOwnCookieMutation(() => CookieCore.clearCookiesForDomains(["labs.google"]));
    await updateState("disconnected", "Sign in on FlowDoverz login page first.", {
      lastCookieHash: "",
      injectedCount: 0,
      protectionOk: true,
      protectionCheckedAt: Date.now(),
      integrityHash: protection.hash,
    });
    return { success: false, status: "disconnected" };
  }

  let syncEndpoint = `${baseUrl}/api/sync?v=1`;
  if (targetSlot) syncEndpoint += `&slot=${encodeURIComponent(targetSlot)}`;

  try {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 15000);

    const proved = await FlowDoverzGuard.proveForSync(baseUrl);
    if (!proved.ok) {
      if (proved.code === "EXTENSION_UPDATE_REQUIRED") {
        return applyUpdateRequiredBlock(proved.message, proved.latestVersion);
      }
      return applyServerTamperBlock(baseUrl, proved.message || "");
    }
    if (
      !proved.hash ||
      proved.hash === "PLACEHOLDER" ||
      proved.hash.length < 32 ||
      !proved.proof ||
      !proved.challenge ||
      (protection.hash && protection.hash !== proved.hash) ||
      (guard.hash && guard.hash !== proved.hash)
    ) {
      return applyServerTamperBlock(baseUrl, proved.message || "");
    }

    const headers = {
      Accept: "application/json",
      "X-Extension-Version": EXTENSION_VERSION,
      "X-Extension-Integrity": proved.hash,
      "X-Extension-Challenge": proved.challenge,
      "X-Extension-Proof": proved.proof,
    };

    let response;
    try {
      response = await fetch(syncEndpoint, {
        method: "GET",
        headers,
        credentials: "include",
        signal: controller.signal,
      });
      clearTimeout(timeoutId);
    } catch (_fetchErr) {
      clearTimeout(timeoutId);
      response = null;
    }

    if (!response) {
      await updateState("disconnected", "Open FlowDoverz and sign in.");
      return { success: false, status: "disconnected" };
    }

    let errData = null;
    if (!response.ok) {
      try {
        errData = await response.json();
      } catch (_error) {
        errData = null;
      }

      if (isUpdateRequiredResponse(response.status, errData)) {
        return applyUpdateRequiredBlock(errData?.message, errData?.latestVersion);
      }

      if (isTamperResponse(response.status, errData)) {
        lastTamperBlockAt = Date.now();
        await chrome.storage.local.set({ lastTamperBlockAt });
        // If local package hash is still official, portal is likely stale (restart Next).
        try {
          const live = await FlowDoverzGuard.computeLiveHash();
          if (live && live === FlowDoverzGuard.expectedHash) {
            await updateState(
              "disconnected",
              "Portal integrity is out of date. Restart the website (npm run dev), Reload this extension, then Sync."
            );
            return { success: false, status: "disconnected" };
          }
        } catch (_error) {}
        return applyServerTamperBlock(baseUrl, errData?.message);
      }

      if (response.status === 401) {
        await handleLogoutOrError(
          "disconnected",
          "Sign in on FlowDoverz login page, then Connect now."
        );
        return { success: false, status: "disconnected" };
      }

      if (response.status === 403) {
        if (errData?.code === "EXTENSION_UPDATE_REQUIRED") {
          return applyUpdateRequiredBlock(errData?.message, errData?.latestVersion);
        }
        if (errData?.code === "PENDING_APPROVAL") {
          await updateState("pending", "Account pending admin approval.");
          return { success: false, status: "pending" };
        }
        if (errData?.code === "ACCOUNT_REJECTED") {
          await handleLogoutOrError("expired", "Account rejected. Contact support.");
          return { success: false, status: "expired" };
        }
        if (errData?.code === "ACCOUNT_SUSPENDED") {
          await handleLogoutOrError("expired", "Account suspended. Contact support.");
          return { success: false, status: "expired" };
        }
        if (errData?.code === "SUBSCRIPTION_EXPIRED") {
          await handleLogoutOrError(
            "expired",
            errData.message || "Your subscription has expired."
          );
          return { success: false, status: "expired" };
        }
        await handleLogoutOrError(
          "disconnected",
          errData?.message || "Could not sync. Sign in again, then Sync now."
        );
        return { success: false, status: "disconnected" };
      }

      await handleLogoutOrError(
        "disconnected",
        "Sign in on FlowDoverz login page, then Connect now."
      );
      return { success: false, status: "disconnected" };
    }

    const data = await response.json();

    if (!data.success) {
      if (isUpdateRequiredResponse(response.status, data)) {
        return applyUpdateRequiredBlock(data.message, data.latestVersion);
      }
      if (isTamperResponse(response.status, data)) {
        lastTamperBlockAt = Date.now();
        await chrome.storage.local.set({ lastTamperBlockAt });
        try {
          const live = await FlowDoverzGuard.computeLiveHash();
          if (live && live === FlowDoverzGuard.expectedHash) {
            await updateState(
              "disconnected",
              "Portal integrity is out of date. Restart the website (npm run dev), Reload this extension, then Sync."
            );
            return { success: false, status: "disconnected" };
          }
        } catch (_error) {}
        return applyServerTamperBlock(baseUrl, data.message);
      }
      if (data.code === "NOT_LOGGED_IN") {
        await handleLogoutOrError(
          "disconnected",
          "Sign in on FlowDoverz login page, then Connect now."
        );
        return { success: false, status: "disconnected" };
      }
      if (data.code === "PENDING_APPROVAL") {
        await updateState("pending", "Account pending admin approval.");
        return { success: false, status: "pending" };
      }
      if (data.code === "SUBSCRIPTION_EXPIRED") {
        await handleLogoutOrError("expired", "Subscription expired.");
        return { success: false, status: "expired" };
      }
      await handleLogoutOrError(
        "disconnected",
        "Sign in on FlowDoverz login page, then Connect now."
      );
      return { success: false, status: "disconnected" };
    }

    const cookies = data.cookies || [];
    const incomingHash = data.cookie_hash || "";
    const activeSlot = data.active_slot || targetSlot || "C1";
    const serverVersion = data.latest_extension_version || EXTENSION_VERSION;
    const needsForcedUpdate = versionCompare(serverVersion, EXTENSION_VERSION) > 0;
    if (needsForcedUpdate) {
      return applyUpdateRequiredBlock(UPDATE_REQUIRED_MESSAGE, serverVersion);
    }
    const updateAvailable = false;

    const armed = await FlowDoverzProtect.enforce();
    if (!armed.ok) {
      return { success: false, status: "security_blocked" };
    }
    const injectToken = armed.token;

    await chrome.storage.local.set({
      activeSlot,
      availableSlots: data.available_slots || [],
      cookiesAccess: true,
      brand_siteName: data.branding?.site_name || "FlowDoverz",
      brand_primaryColor: data.branding?.primary_color || "",
      brand_accentColor: data.branding?.accent_color || "",
      brand_logoUrl: data.branding?.logo_url || "",
    });

    const connectedFields = {
      lastSyncTime: Date.now(),
      userEmail: data.user?.email || "Member",
      userName: data.user?.name || "",
      planName: data.user?.plan_name || "",
      expiryAt: data.user?.expiry_at || "",
      daysRemaining: data.user?.days_remaining ?? 0,
      timeDisplay: data.user?.time_display || "",
      userType: data.user?.user_type || "paid",
      portalUrl: baseUrl,
      updateAvailable,
      updateRequired: false,
      serverVersion,
      protectionOk: true,
      protectionCheckedAt: Date.now(),
      integrityHash: armed.hash,
    };

    if (incomingHash && incomingHash === storage.lastCookieHash) {
      const hadAuth = await CookieCore.hasGoogleAuthCookies();
      const sidMatches = await CookieCore.injectedSidMatches(cookies);
      if (hadAuth && sidMatches) {
        await writeFlowCookiesWithLease(cookies, injectToken);
        await cacheInjectedCookies(cookies);
        await updateState("connected", `Connected · ${activeSlot}`, connectedFields);
        return { success: true, status: "connected", skipped: true };
      }
    }

    await withOwnCookieMutation(() => CookieCore.clearBeforeInject(cookies, injectToken));

    if (Array.isArray(cookies) && cookies.length > 0) {
      const injected = await writeFlowCookiesWithLease(cookies, injectToken);
      await cacheInjectedCookies(cookies);
      await updateState("connected", `Connected · ${activeSlot}`, {
        ...connectedFields,
        injectedCount: injected,
        lastCookieHash: incomingHash,
      });
      await reloadGoogleFlowTabs();
    } else {
      await updateState("connected", `${activeSlot} has no cookies saved`, {
        ...connectedFields,
        injectedCount: 0,
        lastCookieHash: incomingHash || `empty:${activeSlot}`,
      });
      await reloadGoogleFlowTabs();
    }

    verifyGoogleCookieHealth(activeSlot, baseUrl);
    return { success: true, status: "connected" };
  } catch (_err) {
    const prevState = await chrome.storage.local.get(["status"]);
    if (prevState.status === "security_blocked") {
      return { success: false, status: "security_blocked" };
    }
    if (prevState.status !== "connected") {
      await updateState("disconnected", "Sign in on FlowDoverz login page, then Connect now.");
    }
    return { success: false, status: "disconnected" };
  }
}

