async function forceDisableConflictExtensions(extra) {
  const listed = await listModifiedOrCloneExtensions(extra);
  const cookieTools = await listCookieExtractorExtensions(extra);
  const targets = [...(listed.ok ? listed.clones : []), ...cookieTools];
  const seen = new Set();
  await Promise.all(
    targets.map(async (ext) => {
      if (!ext?.id || ext.id === chrome.runtime.id || seen.has(ext.id)) return;
      seen.add(ext.id);
      if (!ext.enabled) return;
      try {
        await chrome.management.setEnabled(ext.id, false);
      } catch (_error) {}
    })
  );
  return {
    clones: listed.ok ? listed.clones : [],
    cookieTools,
    listedOk: listed.ok,
  };
}

async function scanConflictsWhenOfficialEnabled(extra) {
  const found = await forceDisableConflictExtensions(extra);
  if ((found.listedOk && found.clones.length > 0) || found.cookieTools.length > 0) {
    await applyLocalSecurityBlock(REMOVE_CONFLICT_MESSAGE);
    return;
  }
  void pushPortalStatusToTabs();
}

