/** Detect other FlowDoverz / modified lab builds still installed in Chrome. */
function isModifiedOrCloneExtension(ext, selfId) {
  if (!ext) return false;
  if (ext.id === selfId) return false;
  if (ext.type && ext.type !== "extension") return false;
  const name = String(ext.name || "");
  const shortName = String(ext.shortName || "");
  const versionName = String(ext.versionName || "");
  const description = String(ext.description || "");
  const blob = `${name}\n${shortName}\n${versionName}\n${description}`;
  // Lab / attacker markers
  if (/modified\s*test/i.test(blob)) return true;
  if (/\(modified/i.test(name)) return true;
  if (/cookie protection removed/i.test(description)) return true;
  if (/forged integrity/i.test(description)) return true;
  if (/noprotect/i.test(blob)) return true;
  if (/-modified\b/i.test(versionName)) return true;
  // Any other FlowDoverz / FlowBridge copy (even if it still has management)
  if (
    /\bflowdoverz\b/i.test(name) ||
    /\bflowdoverz\b/i.test(shortName) ||
    /\bflowbridge\b/i.test(name) ||
    /\bflowbridge\b/i.test(shortName)
  ) {
    return true;
  }
  return false;
}

/** True when files in THIS install no longer match the official packaged hash. */
async function isSelfPackageChanged() {
  try {
    if (!self.FlowDoverzGuard || typeof FlowDoverzGuard.computeLiveHash !== "function") {
      return false;
    }
    const live = await FlowDoverzGuard.computeLiveHash();
    const expected = FlowDoverzGuard.expectedHash;
    if (!live || !expected || expected === "PLACEHOLDER") return false;
    return live !== expected;
  } catch (_error) {
    return false;
  }
}

/** Official is clean again — unblock immediately so Sync works without a 30min cooldown. */
async function unlockOfficialAfterClean() {
  const prev = await chrome.storage.local.get([
    "status",
    "lastTamperBlockAt",
    "updateRequired",
    "securityReason",
  ]);
  if (prev.updateRequired === true || prev.securityReason === "update_required") {
    return false;
  }
  const wasBlocked =
    prev.status === "security_blocked" ||
    Number(prev.lastTamperBlockAt || lastTamperBlockAt || 0) > 0;
  lastTamperBlockAt = 0;
  const next = {
    lastTamperBlockAt: 0,
    protectionOk: true,
  };
  if (prev.status === "security_blocked") {
    next.status = "disconnected";
    next.statusMessage = "Modified extension removed. Click Sync now.";
    next.securityReason = "";
    next.securityDetail = "";
  }
  await chrome.storage.local.set(next);
  return wasBlocked;
}

async function listCookieExtractorExtensions(extra) {
  try {
    const all = await chrome.management.getAll();
    if (extra && extra.id && !all.some((ext) => ext.id === extra.id)) {
      all.push(extra);
    }
    return all.filter((ext) => FlowDoverzProtect.isBlockedCookieExtension(ext));
  } catch (_error) {
    return [];
  }
}

/** @returns {{ ok: boolean, clones: object[] }} */
async function listModifiedOrCloneExtensions(extra) {
  try {
    const selfId = chrome.runtime.id;
    const all = await chrome.management.getAll();
    if (extra && extra.id && !all.some((ext) => ext.id === extra.id)) {
      all.push(extra);
    }
    return {
      ok: true,
      clones: all.filter((ext) => isModifiedOrCloneExtension(ext, selfId)),
    };
  } catch (_error) {
    // Unknown — do not pretend "no clones" (that was clearing the dashboard banner).
    return { ok: false, clones: [] };
  }
}

async function buildPortalStatusPayload(extra) {
  const listed = await listModifiedOrCloneExtensions(extra);
  const cookieTools = await listCookieExtractorExtensions(extra);
  const selfChanged = await isSelfPackageChanged();
  const clonesPresent = listed.ok && listed.clones.length > 0;
  const cookiePresent = cookieTools.length > 0;
  const stored = await chrome.storage.local.get(["updateRequired", "statusMessage", "serverVersion"]);
  const updateRequired = stored.updateRequired === true;

  if (updateRequired) {
    return {
      present: true,
      tampered: false,
      modifiedPresent: false,
      updateRequired: true,
      canClear: false,
      latestVersion: stored.serverVersion || "",
      message: stored.statusMessage || UPDATE_REQUIRED_MESSAGE,
    };
  }

  if (!listed.ok && !selfChanged && !cookiePresent) {
    return {
      present: true,
      tampered: false,
      modifiedPresent: null,
      updateRequired: false,
      canClear: false,
      message: null,
    };
  }

  if (clonesPresent || cookiePresent || selfChanged) {
    return {
      present: true,
      tampered: true,
      modifiedPresent: true,
      updateRequired: false,
      canClear: false,
      message: selfChanged && !clonesPresent && !cookiePresent
        ? SELF_CHANGED_MESSAGE
        : REMOVE_CONFLICT_MESSAGE,
    };
  }

  return {
    present: true,
    tampered: false,
    modifiedPresent: false,
    updateRequired: false,
    canClear: true,
    message: null,
  };
}

async function pushPortalStatusToTabs(extra) {
  try {
    const payload = await buildPortalStatusPayload(extra);
    if (payload.modifiedPresent === false) {
      const shouldResume = await unlockOfficialAfterClean();
      if (shouldResume) {
        void performCookieSync("", { force: true });
      }
    }
    const encoded = JSON.stringify(payload);
    if (encoded === lastPortalStatusJson) return;
    lastPortalStatusJson = encoded;
    await chrome.storage.local.set({
      portalStatusPush: payload,
      portalStatusAt: Date.now(),
    });
    const tabs = await chrome.tabs.query({
      url: [
        "http://localhost/*",
        "http://127.0.0.1/*",
        "https://flow.doverz.com/*",
        "https://*.doverz.com/*",
        "https://flowdoverz.app/*",
        "https://*.flowdoverz.app/*",
      ],
    });
    await Promise.all(
      tabs.map((tab) =>
        tab.id
          ? chrome.tabs
              .sendMessage(tab.id, { action: "PORTAL_STATUS_PUSH", payload })
              .catch(() => {})
          : Promise.resolve()
      )
    );
  } catch (_error) {
    // ignore
  }
}

chrome.tabs.onUpdated.addListener(async (tabId, changeInfo, tab) => {
  const url = String(tab.url || changeInfo.url || "");
  if (!url || url.startsWith("chrome://") || url.startsWith("edge://")) return;
  if (!/labs\.google/i.test(url)) return;

  // Re-apply cookies as soon as Flow starts loading — waiting for "complete" is too late for Ultra.
  if (changeInfo.status === "loading" && /fx\/tools\/flow/i.test(url)) {
    void applyCachedCookiesOnFlowOpen(tabId);
    return;
  }

  if (changeInfo.status !== "complete") return;
  const now = Date.now();
  if (now - lastTabSyncAt < 30 * 1000) return;
  lastTabSyncAt = now;
  performCookieSync();
});

