async function handleCookieTheftAttempt(reason) {
  if (theftHandling || ownCookieMutationDepth > 0) return;
  theftHandling = true;
  try {
    const found = await forceDisableConflictExtensions();
    const hasTools =
      (found.listedOk && found.clones.length > 0) || found.cookieTools.length > 0;
    if (hasTools) {
      await applyLocalSecurityBlock(REMOVE_CONFLICT_MESSAGE);
      return;
    }
    await handleLogoutOrError(
      "disconnected",
      reason || "Session cookies were changed. Sign in and Sync again."
    );
  } finally {
    theftHandling = false;
  }
}

try {
  chrome.cookies.onChanged.addListener((changeInfo) => {
    if (!changeInfo || ownCookieMutationDepth > 0 || theftHandling) return;
    const cookie = changeInfo.cookie;
    if (!CookieCore.isTheftWatchCookie(cookie)) return;

    chrome.storage.local.get(["status"]).then((state) => {
      if (state.status !== "connected") return;

      if (changeInfo.removed) {
        void handleCookieTheftAttempt("Session cookies were removed. Sign in and Sync again.");
        return;
      }

      const expected = injectedCookieCache.find(
        (item) => item && item.name === cookie.name
      );
      if (!expected || typeof expected.value !== "string") return;
      if (expected.value !== cookie.value) {
        void handleCookieTheftAttempt("Session cookies were modified. Sign in and Sync again.");
      }
    });
  });
} catch (_error) {}

