        prev.securityReason !== "cookie_tool" &&
        prev.securityReason !== "update_required" &&
        prev.updateRequired !== true
      ) {
        lastTamperBlockAt = 0;
        await chrome.storage.local.set({
          status: "disconnected",
          statusMessage: "Sign in on FlowDoverz, then Sync now.",
          securityReason: "",
          securityDetail: "",
          protectionOk: true,
          lastTamperBlockAt: 0,
        });
      }
      const protection = await FlowDoverzProtect.enforce();
      if (!protection.ok) {
        // Soft-lock only — enforce/block already sets status; avoid second tab reload.
        await FlowDoverzGuard.block(protection.message);
