    };
  }

  function triggerSync(options = {}) {
    const { silent = false, slot = "" } = options;
    if (!silent) setLoading(true);

    return new Promise((resolve) => {
      let settled = false;
      const finish = (result) => {
        if (settled) return;
        settled = true;
        if (!silent) setLoading(false);
        loadState().then(() => resolve(result || { success: false, status: "disconnected" }));
      };

      const timer = window.setTimeout(() => {
        finish({
          success: false,
          status: "disconnected",
          message: "Sync timed out. Open FlowDoverz, sign in, then try again.",
        });
      }, 20000);

      try {
        chrome.runtime.sendMessage({ action: "TRIGGER_SYNC", slot }, (result) => {
          window.clearTimeout(timer);
          const err = chrome.runtime.lastError;
          if (err) {
            finish({
              success: false,
              status: "disconnected",
              message: err.message || "Extension wake failed. Reopen popup and Sync again.",
            });
            return;
          }
          finish(result);
        });
      } catch (_error) {
        window.clearTimeout(timer);
        finish({
          success: false,
          status: "disconnected",
          message: "Could not reach extension. Reload it in Lemur, then Sync again.",
        });
      }
    });
  }

  if (dashboardBtn) {
    dashboardBtn.addEventListener("click", () => {
      chrome.runtime.sendMessage({ action: "OPEN_DASHBOARD" });
    });
  }

  if (syncNowBtn) {
    syncNowBtn.addEventListener("click", async () => {
      const result = await triggerSync();
      if (result?.success) {
        showToast(result.skipped ? "Already up to date" : "Connected successfully");
      } else if (result?.status === "security_blocked") {
        showToast("Security blocked — fix the issue shown above");
      } else if (result?.message) {
        showToast(result.message);
      } else {
        showToast("Could not connect — open FlowDoverz, sign in, then Sync");
      }
    });
  }

  if (refreshBtn) {
    refreshBtn.addEventListener("click", () => triggerSync());
  }

  if (copyEmailBtn) {
    copyEmailBtn.addEventListener("click", async () => {
      const email = userEmail?.textContent?.trim();
      if (!email || email === "—") return;
      try {
        await navigator.clipboard.writeText(email);
        showToast("Email copied");
      } catch {
        showToast("Could not copy email");
      }
    });
  }

  chrome.storage.onChanged.addListener(() => loadState());

  async function bootPopup() {
    await loadState();
    try {
      // If local package hash matches again, clear a stale lock before the security poll.
      const unlocked = await chrome.runtime.sendMessage({ action: "TRY_UNLOCK_OFFICIAL" });
      if (unlocked?.cleared) await loadState();
    } catch (_error) {}
    try {
      await chrome.runtime.sendMessage({ action: "CHECK_SECURITY" });
      await loadState();
    } catch (_error) {
      // ignore
    }
    const state = await chrome.storage.local.get(["status"]);
    // Light poll on open only when already connected.
    if (state.status === "connected") {
      await triggerSync({ silent: true });
    }
  }

  bootPopup();

  window.addEventListener("unload", () => {
    if (countdownTimer) window.clearInterval(countdownTimer);
    if (toastTimer) window.clearTimeout(toastTimer);
  });
})();
