:root {
  color-scheme: dark;
  --bg: #080810;
  --panel: #0c0e16;
  --line: rgba(255, 255, 255, 0.08);
  --line-accent: rgba(34, 211, 238, 0.28);
  --text: #f1f5f9;
  --muted: #94a3b8;
  --dim: #64748b;
  --primary: #22d3ee;
  --primary-dark: #06b6d4;
  --accent: #34d399;
  --error: #fb7185;
  --warning: #fbbf24;
  --success: #34d399;
  --shadow: 0 16px 40px rgba(0, 0, 0, 0.35);
}

* {
  box-sizing: border-box;
}

[hidden] {
  display: none !important;
}

html,
body {
  width: 360px;
  margin: 0;
  overflow: hidden;
  overflow-x: hidden;
  overflow-y: hidden;
}

body {
  position: relative;
  background: var(--bg);
  color: var(--text);
  font: 13px/1.45 Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

.ambient {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(ellipse 85% 55% at 50% -15%, rgba(34, 211, 238, 0.16), transparent 55%),
    radial-gradient(ellipse 55% 45% at 100% 100%, rgba(52, 211, 153, 0.09), transparent 50%);
}

main {
  position: relative;
  z-index: 1;
  padding: 14px 14px 12px;
}

.top-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 12px;
}

.brand-lockup {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}

.brand-lockup img {
  width: 36px;
  height: 36px;
  object-fit: contain;
  filter: drop-shadow(0 0 12px rgba(34, 211, 238, 0.2));
}

.brand-copy {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.brand-copy strong {
  font-size: 15px;
  font-weight: 900;
  letter-spacing: -0.3px;
}

.brand-tagline {
  color: rgba(34, 211, 238, 0.72);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

.brand-copy span {
  color: var(--dim);
  font-size: 10px;
  font-weight: 600;
}

.icon-btn {
  display: inline-flex;
  width: 34px;
  height: 34px;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.04);
  color: var(--muted);
  cursor: pointer;
  transition: all 0.2s ease;
}

.icon-btn:hover {
  color: var(--primary);
  border-color: var(--line-accent);
  background: rgba(34, 211, 238, 0.08);
}

.icon-btn.spinning svg {
  animation: spin 0.8s linear infinite;
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

.update-banner {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 10px;
  padding: 9px 11px;
  border: 1px solid rgba(251, 191, 36, 0.35);
  border-radius: 12px;
  background: rgba(251, 191, 36, 0.08);
  color: #fde68a;
  font-size: 10px;
  line-height: 1.35;
}

.update-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--warning);
  box-shadow: 0 0 8px rgba(251, 191, 36, 0.8);
  flex-shrink: 0;
}

.security-banner {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  margin-bottom: 10px;
  padding: 10px 11px;
  border: 1px solid rgba(251, 113, 133, 0.45);
  border-radius: 12px;
  background: rgba(251, 113, 133, 0.1);
  color: #fecdd3;
}

.security-icon {
  display: inline-flex;
  width: 22px;
  height: 22px;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: rgba(251, 113, 133, 0.25);
  color: #fff1f2;
  font-weight: 900;
  font-size: 13px;
  flex-shrink: 0;
}

.security-copy strong {
  display: block;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.02em;
  text-transform: uppercase;
  color: #ffe4e6;
}

.security-copy p {
  margin: 3px 0 0;
  font-size: 10px;
  line-height: 1.4;
  color: #fecdd3;
}

.glass-card {
  border: 1px solid var(--line);
  border-radius: 14px;
  background: linear-gradient(160deg, rgba(255, 255, 255, 0.04), rgba(255, 255, 255, 0.01));
  backdrop-filter: blur(10px);
  box-shadow: var(--shadow);
}

.status-card {
  padding: 12px 13px;
  margin-bottom: 10px;
  border-left: 3px solid var(--error);
}

.status-card.connected {
  border-left-color: var(--success);
}

.status-card.pending,
.status-card.expired {
  border-left-color: var(--warning);
}

.status-card.security_blocked {
  border-left-color: var(--error);
  background: linear-gradient(160deg, rgba(251, 113, 133, 0.08), rgba(255, 255, 255, 0.01));
}

.status-row {
  display: flex;
  align-items: flex-start;
  gap: 11px;
}

.status-dot {
  width: 10px;
  height: 10px;
  margin-top: 5px;
  border-radius: 50%;
  flex-shrink: 0;
}

.status-dot.connected {
  background: var(--success);
  box-shadow: 0 0 12px rgba(52, 211, 153, 0.85);
  animation: pulse 2s ease-in-out infinite;
}

.status-dot.disconnected {
  background: var(--error);
  box-shadow: 0 0 10px rgba(251, 113, 133, 0.65);
}

.status-dot.pending,
.status-dot.expired {
  background: var(--warning);
}

.status-dot.security_blocked {
  background: var(--error);
  box-shadow: 0 0 10px rgba(251, 113, 133, 0.65);
}

@keyframes pulse {
  0%,
  100% {
    transform: scale(1);
    opacity: 1;
  }
  50% {
    transform: scale(1.12);
    opacity: 0.88;
  }
}

.status-copy h2 {
  margin: 0;
  font-size: 14px;
  font-weight: 800;
  letter-spacing: -0.2px;
}

.status-copy p {
  margin: 4px 0 0;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.4;
}

.profile-card {
  padding: 11px 12px;
  margin-bottom: 10px;
}

.profile-main {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}

.avatar-fallback {
  display: flex;
  width: 40px;
  height: 40px;
  align-items: center;
  justify-content: center;
  border-radius: 12px;
  background: linear-gradient(135deg, rgba(34, 211, 238, 0.22), rgba(52, 211, 153, 0.18));
  border: 1px solid var(--line-accent);
  color: #ecfeff;
  font-size: 14px;
  font-weight: 900;
  flex-shrink: 0;
}

.profile-copy {
  min-width: 0;
  flex: 1;
}

.profile-copy strong {
  display: block;
  overflow: hidden;
  font-size: 14px;
  font-weight: 800;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.profile-copy span {
  display: block;
  overflow: hidden;
  margin-top: 2px;
  color: var(--primary);
  font-size: 10px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.copy-btn {
  flex-shrink: 0;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 4px 10px;
  background: rgba(255, 255, 255, 0.03);
  color: var(--muted);
  font: inherit;
  font-size: 10px;
  font-weight: 700;
  cursor: pointer;
}

.copy-btn:hover {
  color: var(--text);
  border-color: var(--line-accent);
}

.metrics {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
  margin-bottom: 8px;
}

.metric {
  padding: 10px 11px;
}

.metric-label {
  display: block;
  margin-bottom: 4px;
  color: var(--dim);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.metric strong {
  display: block;
  color: #fff;
  font-size: 16px;
  font-weight: 900;
  letter-spacing: -0.3px;
}

.metric:first-child strong {
  color: var(--primary);
  font-size: 14px;
}

.time-bar-wrap {
  margin-bottom: 10px;
}

.time-bar {
  height: 4px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.06);
  overflow: hidden;
}

.time-bar-fill {
  width: 100%;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, var(--primary-dark), var(--accent));
  transition: width 0.4s ease;
}

.session-card {
  padding: 11px 12px;
  margin-bottom: 10px;
}

.session-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 8px;
}

.session-head label {
  color: #a5f3fc;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.session-hint {
  color: var(--dim);
  font-size: 9px;
}

.select-wrap {
  position: relative;
}

.select-wrap::after {
  content: "";
  position: absolute;
  top: 50%;
  right: 14px;
  width: 7px;
  height: 7px;
  margin-top: -5px;
  border-right: 2px solid var(--primary);
  border-bottom: 2px solid var(--primary);
  transform: rotate(45deg);
  pointer-events: none;
}

#slotSelect {
  width: 100%;
  min-height: 40px;
  appearance: none;
  -webkit-appearance: none;
  border: 1px solid rgba(34, 211, 238, 0.28);
  border-radius: 11px;
  outline: 0;
  padding: 0 36px 0 12px;
  background: rgba(8, 8, 16, 0.9);
  color: #fff;
  font: inherit;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  line-height: 40px;
}

#slotSelect:focus {
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(34, 211, 238, 0.12);
}

.session-legend {
  display: flex;
  gap: 12px;
  margin-top: 8px;
  color: var(--dim);
  font-size: 9px;
}

.session-legend span {
  display: inline-flex;
  align-items: center;
  gap: 5px;
}

.dot-live,
.dot-empty {
  display: inline-block;
  width: 7px;
  height: 7px;
  border-radius: 50%;
}

.dot-live {
  background: var(--success);
  box-shadow: 0 0 6px rgba(52, 211, 153, 0.7);
}

.dot-empty {
  background: #475569;
}

.actions {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.btn-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.btn {
  display: inline-flex;
  width: 100%;
  min-height: 42px;
  align-items: center;
  justify-content: center;
  border: 0;
  border-radius: 12px;
  font: inherit;
  font-size: 12px;
  font-weight: 800;
  cursor: pointer;
  transition: transform 0.15s ease, opacity 0.15s ease, box-shadow 0.15s ease;
}

.btn:active:not(:disabled) {
  transform: scale(0.98);
}

.btn-primary {
  background: linear-gradient(100deg, var(--primary-dark), var(--accent));
  color: #041016;
  box-shadow: 0 0 22px rgba(34, 211, 238, 0.25);
}

.btn-primary:hover:not(:disabled) {
  box-shadow: 0 0 30px rgba(34, 211, 238, 0.38);
}

.btn-primary:disabled {
  opacity: 0.45;
  cursor: not-allowed;
  box-shadow: none;
}

.btn-secondary {
  border: 1px solid var(--line-accent);
  background: rgba(34, 211, 238, 0.06);
  color: #a5f3fc;
}

.btn-secondary:hover:not(:disabled) {
  background: rgba(34, 211, 238, 0.12);
}

.btn-secondary:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.popup-footer {
  margin-top: 12px;
  padding-top: 10px;
  border-top: 1px solid var(--line);
  text-align: center;
}

.popup-footer span {
  color: var(--dim);
  font-size: 10px;
}

.toast {
  position: fixed;
  left: 50%;
  bottom: 12px;
  z-index: 20;
  max-width: calc(100% - 24px);
  transform: translateX(-50%);
  padding: 8px 14px;
  border-radius: 10px;
  border: 1px solid var(--line-accent);
  background: rgba(8, 10, 16, 0.96);
  color: #ecfeff;
  font-size: 11px;
  font-weight: 600;
  box-shadow: var(--shadow);
}

.loading-overlay {
  position: absolute;
  inset: 0;
  z-index: 15;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(8, 8, 16, 0.55);
  backdrop-filter: blur(2px);
}

.spinner {
  width: 28px;
  height: 28px;
  border: 2px solid rgba(34, 211, 238, 0.2);
  border-top-color: var(--primary);
  border-radius: 50%;
  animation: spin 0.7s linear infinite;
}
