// Portal auth — clients must sign in on /login; guests get no cookies
(function () {
  "use strict";

  const path = (location.pathname || "").replace(/\/+$/, "") || "/";
  const isLoginPage =
    path === "/login" ||
    path === "/signup" ||
    path.endsWith("/login") ||
    path.endsWith("/signup");

  function detectPortalAuth() {
    const bridge = document.getElementById("flowdoverz-auth-bridge");

    if (bridge) {
      const isLoggedIn = bridge.getAttribute("data-logged-in") === "1";
      const email = bridge.getAttribute("data-email") || "";
      const days = bridge.getAttribute("data-days") || 0;
      const baseUrl = bridge.getAttribute("data-base-url") || location.origin;
      const realLogin = isLoggedIn && email.includes("@");

      try {
        chrome.runtime.sendMessage({
          action: "PORTAL_AUTH_DETECTED",
          isLoggedIn: realLogin,
          email,
          days,
          origin: baseUrl,
        });
      } catch (_error) {}
      return;
    }

    try {
      const raw = localStorage.getItem("flowdoverz_session");
      if (!raw) {
        if (isLoginPage) {
          chrome.runtime.sendMessage({
            action: "PORTAL_AUTH_DETECTED",
            isLoggedIn: false,
            origin: location.origin,
          });
        }
        return;
      }
      const session = JSON.parse(raw);
      if (!session?.email) return;

      chrome.runtime.sendMessage({
        action: "PORTAL_AUTH_DETECTED",
        isLoggedIn: true,
        email: session.email,
        days: 14,
        origin: location.origin,
      });
    } catch (_error) {}
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", detectPortalAuth);
  } else {
    detectPortalAuth();
  }
  setInterval(detectPortalAuth, 2000);
})();

