  function matchModelName(label) {
    const text = normalize(label);
    if (!text) return "";
    if (/lower\s*priority/i.test(text) && !/\bquality\b|\bfast\b|\bomni\b/i.test(text)) return "";

    const compact = text.toLowerCase().replace(/[-\s_]+/g, "");
    for (const name of FAKE_MODELS) {
      const nameLower = name.toLowerCase();
      const compactName = nameLower.replace(/[-\s_]+/g, "");
      if (text.toLowerCase() === nameLower || compact === compactName) return name;
      if (text.toLowerCase().startsWith(nameLower) && text.length < name.length + 60) return name;
      if (compact.startsWith(compactName) && compact.length < compactName.length + 40) return name;
    }
    if (/\bquality\b/i.test(text) && (/veo/i.test(text) || /3\.1/i.test(text))) return "Veo 3.1 - Quality";
    if (/\bfast\b/i.test(text) && (/veo/i.test(text) || /3\.1/i.test(text))) return "Veo 3.1 - Fast";
    if (/\blite\b/i.test(text) && (/veo/i.test(text) || /3\.1/i.test(text)) && !/priority/i.test(text)) {
      return "Veo 3.1 - Lite";
    }
    if (/\bomni\b/i.test(text)) return "Omni Flash";
    return "";
  }

  function pendingCost() {
    return Number(CREDIT_MAP[selectedModel] || CREDIT_MAP[DEFAULT_MODEL] || 5);
  }

  function setSelectedModel(name) {
    const matched = matchModelName(name) || name;
    if (!matched || CREDIT_MAP[matched] == null) return;
    selectedModel = matched;
    fakeModelName = matched;
    publishSelectedModel();
    persist();
  }

  /** Jin Tools: cleanText */
  function cleanText(value) {
    return normalize(value);
  }

  function simulateClick(el) {
    if (!(el instanceof HTMLElement)) return;
    try {
      el.focus({ preventScroll: true });
    } catch (_error) {}
    const r = el.getBoundingClientRect();
    const x = r.left + Math.max(1, r.width / 2);
    const y = r.top + Math.max(1, r.height / 2);
    const opts = { bubbles: true, cancelable: true, composed: true, view: window, clientX: x, clientY: y };
    try {
      el.dispatchEvent(
        new PointerEvent("pointerdown", Object.assign({ pointerId: 1, pointerType: "mouse", buttons: 1 }, opts))
      );
    } catch (_error) {}
    try {
      el.dispatchEvent(new MouseEvent("mousedown", opts));
      el.dispatchEvent(new MouseEvent("mouseup", opts));
      el.dispatchEvent(new MouseEvent("click", opts));
      el.click();
    } catch (_error) {}
  }

  function findModelRow(el) {
    let current = el;
    for (let depth = 0; current && depth < 6; depth += 1) {
      const role = current.getAttribute && current.getAttribute("role");
      if (role === "menuitem" || role === "option" || role === "menuitemradio") return current;
      if (current.matches && current.matches("button, [role='button'], li")) return current;
      current = current.parentElement;
    }
    return el;
  }

  function findLowerPriorityInOpenMenu() {
    const menus = document.querySelectorAll(
      '[role="menu"], [role="listbox"], [data-radix-menu-content]'
    );
    for (const menu of menus) {
      const nodes = menu.querySelectorAll(
        '[role="menuitem"], [role="option"], [role="menuitemradio"], button, div, li, span'
      );
      for (const el of nodes) {
        if (!(el instanceof HTMLElement)) continue;
        const text = normalize(el.textContent || "");
        if (!text || text.length > 140) continue;
        if (!/lower\s*priority/i.test(text)) continue;
        return findModelRow(el);
      }
    }
    return null;
  }

  function findVeoLiteInOpenMenu() {
    const menus = document.querySelectorAll(
      '[role="menu"], [role="listbox"], [data-radix-menu-content]'
    );
    for (const menu of menus) {
      const nodes = menu.querySelectorAll(
        '[role="menuitem"], [role="option"], [role="menuitemradio"], button, div, li'
      );
      for (const el of nodes) {
        if (!(el instanceof HTMLElement)) continue;
        const text = normalize(el.textContent || "");
        if (!text || text.length > 140) continue;
        if (/lower\s*priority/i.test(text)) continue;
        if (/\blite\b/i.test(text) && /veo/i.test(text)) return findModelRow(el);
      }
    }
    return null;
  }

  let skipDummyIntercept = false;
  let nativeLpArmed = false;
  let nativeCompatPinAt = 0;

  function nativeAlreadyLowerPriority(el) {
    if (!(el instanceof HTMLElement)) return false;
