  function isNativeGoogleModelPicker(el) {
    if (!(el instanceof HTMLElement)) return false;
    if (
      el.closest(
        "#flowdoverz-dummy-model-menu, #flowdoverz-dummy-chip-label, .flowdoverz-settings-model-select, #flowdoverz-settings-panel"
      )
    ) {
      return false;
    }
    const text = normalize(el.innerText || el.textContent || "");
    if (text.length < 10 || text.length > 1800) return false;
    if (/\bingredients\b/i.test(text) && /\bframes\b/i.test(text)) return false;
    if (/\b4\s*s\b/i.test(text) && /\b8\s*s\b/i.test(text) && /\bvideo\b/i.test(text)) return false;
    return /lower\s*priority/i.test(text);
  }

  function hideNativeGoogleModelPicker() {
    // Jin Tools never hides Flow's native model menu. Hiding it here made
    // clicks look like they did nothing (list closed on the 50ms paint).
    document.querySelectorAll("[data-flowdoverz-hide-native-picker]").forEach((el) => {
      el.removeAttribute("data-flowdoverz-hide-native-picker");
    });
