  /**
   * Dummy UI does not change Google's model. Opening native picker overlays the
   * prompt and blocks typing — do not pin by clicking Google's menu.
   */
  function quietPinNativeForGenerate() {
    if (pinLpBusy || skipDummyIntercept) return;
    pinLpBusy = false;
    try {
      document.documentElement.removeAttribute("data-flowdoverz-pinning");
    } catch (_error) {}
    const blur = document.getElementById("ct-blur-overlay");
    if (blur) blur.remove();
