  function findModelTriggerButton() {
    const tagged = document.querySelector(
      "button[data-fake-model]:not(#flowdoverz-model-select-trigger), [role='button'][data-fake-model]:not(#flowdoverz-model-select-trigger)"
    );
    if (tagged instanceof HTMLElement && !tagged.closest("#flowdoverz-model-select")) return tagged;
    const buttons = document.querySelectorAll("button, [role='button']");
    for (const el of buttons) {
      if (!(el instanceof HTMLElement)) continue;
      if (el.id === "flowdoverz-model-select-trigger" || el.closest("#flowdoverz-model-select")) continue;
      if (isDummyModelUi(el) || isGenerateOrInfoButton(el)) continue;
      if (el.closest('[role="menu"], [role="listbox"]')) continue;
      const text = normalize(el.innerText || el.textContent || "");
      if (!text || text.length > 90) continue;
      if (!/veo|omni|priority|flash|quality|fast|lite/i.test(text)) continue;
      const rect = el.getBoundingClientRect();
      if (rect.width > 100 && rect.height > 18 && rect.height < 56) return el;
    }
    return null;
  }

  function googleReallyOnQuality() {
    const buttons = document.querySelectorAll("button, [role='button']");
    for (const row of buttons) {
      if (!(row instanceof HTMLElement)) continue;
      if (row.closest('[role="menu"], [role="listbox"]')) continue;
      const text = normalize(row.textContent || "");
      if (!/quality/i.test(text) || !/veo/i.test(text)) continue;
      if (/lower\s*priority/i.test(text)) continue;
      const rect = row.getBoundingClientRect();
      if (rect.width > 100 && rect.height > 18 && rect.height < 64) return true;
    }
    return false;
  }

  /** Click LP completely off-screen — user never sees Lower Priority. */
  function prepareLpForClick(lp) {
    lp.removeAttribute("aria-hidden");
    lp.removeAttribute("data-hide-lp");
    lp.removeAttribute("data-flowdoverz-hide-lp");
    lp.style.setProperty("opacity", "0", "important");
    lp.style.setProperty("pointer-events", "auto", "important");
  }

  function restoreLpAfterClick(lp) {
    [
      "display",
      "visibility",
      "opacity",
      "pointer-events",
      "position",
      "left",
      "top",
      "height",
      "width",
      "overflow",
      "z-index",
    ].forEach((p) => lp.style.removeProperty(p));
    lp.removeAttribute("data-hide-lp");
    lp.removeAttribute("data-flowdoverz-hide-lp");
  }

  function clickLowerPriorityNow(lp) {
    if (!(lp instanceof HTMLElement)) return false;
    pinLpBusy = true;
    document.documentElement.setAttribute("data-flowdoverz-pinning", "true");
    // Jin Tools: blur page + elevate LP briefly while selecting it.
    showCtBlurOverlay();
    prepareLpForClick(lp);
    lp.setAttribute("data-elevate-btn", "true");
    simulateClick(lp);
    window.setTimeout(() => simulateClick(lp), 30);
    window.setTimeout(() => {
      restoreLpAfterClick(lp);
      lp.removeAttribute("data-elevate-btn");
      hideCtBlurOverlay();
      pinLpBusy = false;
      document.documentElement.removeAttribute("data-flowdoverz-pinning");
      schedulePaint(true);
    }, 280);
    return true;
  }

  function forceQualityOntoLowerPriority() {
    if (pinLpBusy) return;
    const keepLabel = selectedModel || "Veo 3.1 - Quality";

    const lpOpen = findLowerPriorityInOpenMenu();
    if (lpOpen) {
      clickLowerPriorityNow(lpOpen);
      [120, 400].forEach((ms) =>
        window.setTimeout(() => {
          selectedModel = keepLabel;
          schedulePaint(true);
        }, ms)
      );
      return;
    }

    const trigger = findModelTriggerButton();
    if (!(trigger instanceof HTMLElement)) return;

    pinLpBusy = true;
    document.documentElement.setAttribute("data-flowdoverz-pinning", "true");
    simulateClick(trigger);
    window.setTimeout(() => {
      const lp = findLowerPriorityInOpenMenu();
      if (lp) {
        prepareLpForClick(lp);
        simulateClick(lp);
        window.setTimeout(() => simulateClick(lp), 40);
        window.setTimeout(() => {
          restoreLpAfterClick(lp);
          pinLpBusy = false;
          document.documentElement.removeAttribute("data-flowdoverz-pinning");
          selectedModel = keepLabel;
          schedulePaint(true);
        }, 280);
        return;
      }
      pinLpBusy = false;
      document.documentElement.removeAttribute("data-flowdoverz-pinning");
      selectedModel = keepLabel;
      schedulePaint(true);
    }, 220);
  }

  function isNativeSettingsContext(el) {
    if (!(el instanceof Element)) return false;
    if (el.closest("#flowdoverz-settings-panel")) return true;
    let node = el instanceof HTMLElement ? el : el.parentElement;
    for (let depth = 0; node && depth < 12; depth += 1) {
      const text = normalize(node.innerText || "");
      if (text.length > 20 && text.length < 1200) {
        const hasModes = /\bimage\b/i.test(text) && /\bvideo\b/i.test(text);
        const hasMode2 = /\bframes\b/i.test(text) && /\bingredients\b/i.test(text);
        const hasAspect = /9\s*[:：∕\/.|-]\s*16|16\s*[:：∕\/.|-]\s*9/.test(text);
        const hasDuration = /\b4\s*s\b/i.test(text) && /\b8\s*s\b/i.test(text);
        const hasBatch = /\bx\s*1\b/i.test(text) || /\bx1\b/i.test(text);
        if (hasModes && hasMode2 && (hasAspect || hasDuration || hasBatch)) return true;
      }
      node = node.parentElement;
    }
    return false;
  }

  function findNativeSettingsPanelRoots() {
    const roots = [];
    const candidates = document.querySelectorAll(
      '[role="dialog"], [data-radix-popper-content-wrapper], [data-radix-menu-content], [role="menu"], [data-state="open"], section, div'
    );
    for (const el of candidates) {
      if (!(el instanceof HTMLElement)) continue;
      if (el.id === "flowdoverz-settings-panel" || el.closest("#flowdoverz-settings-panel")) continue;
      if (el.closest(".flowdoverz-settings-model-select")) continue;
      if (!isNativeSettingsContext(el)) continue;
      const rect = el.getBoundingClientRect();
      if (rect.width < 160 || rect.width > 520 || rect.height < 160 || rect.height > 640) continue;
      if (rect.bottom < 0 || rect.top > window.innerHeight) continue;
      const text = normalize(el.innerText || "");
      if (/what\s*do\s*you\s*want\s*to\s*create/i.test(text)) continue;
      if (!/\b(4|6|8)\s*s\b/i.test(text)) continue;
      if (!/\bingredients\b/i.test(text) && !/\bframes\b/i.test(text)) continue;
      roots.push(el);
    }
    roots.sort((a, b) => {
      const ar = a.getBoundingClientRect();
      const br = b.getBoundingClientRect();
      return ar.width * ar.height - br.width * br.height;
    });
    // Keep the innermost card only. Promoting the parent put the dummy on Generate.
    return roots[0] ? [roots[0]] : [];
  }

  let settingsModelKeepUntil = 0;
  let settingsModelLastHeavyAt = 0;
  let settingsModelStablePanel = null;
  let settingsPanelMisses = 0;

  /**
   * Compact Ingredients settings has no native model chip.
   * Dummy row sits in the hole between the divider and 4s/6s/8s.
   */
  function paintJinSettingsPanel() {
    if (!portalConnected) return;
    try {
      const pinned = document.documentElement.getAttribute("data-flowdoverz-dummy-model");
      if (pinned && CREDIT_MAP[pinned] != null && pinned !== selectedModel) {
        selectedModel = pinned;
        fakeModelName = pinned;
      }
    } catch (_error) {}
    const cost = formatBalance(pendingCost());
    const label = selectedModel || DEFAULT_MODEL;
    const panel = findNativeSettingsPanelRoots()[0] || null;
    const keepOpen = isDummyMenuOpen();

    if (!(panel instanceof HTMLElement)) {
      settingsPanelMisses += 1;
      // Dummy list can blink the panel detector — keep it briefly. Never leave
      // the dummy chip parked on the create page after settings close.
      if (keepOpen && settingsPanelMisses < 8) return;
      teardownDummySettingsUi();
      return;
    }
    settingsPanelMisses = 0;
    parkDummyMenu(dummyModelWrap);

    try {
      document.documentElement.setAttribute("data-flowdoverz-settings-open", "1");
    } catch (_error) {}
    sweepStrayDummyWidgets(panel);

    if (keepOpen && dummyModelWrap instanceof HTMLElement && dummyModelWrap.isConnected) {
      attachDummyOverlayHost(dummyModelWrap);
      ensureDummyModelGap(panel);
      paintSettingsBatch(panel);
      const slot = findDummyModelSlot(panel);
      if (slot) {
        placeDummyInPanel(dummyModelWrap, panel, slot, true);
        keepDummyOffGenerate(dummyModelWrap);
      }
      protectDummyModelRows(dummyModelWrap);
      syncDummyLabel(dummyModelWrap, label);
      dockDummyMenu(dummyModelWrap, true);
      restoreComposerGenerate();
      return;
    }
    ensureDummyModelGap(panel);
    paintSettingsBatch(panel);
    const wrap = mountDummyModelOverlay(panel, label);
    restoreComposerGenerate();
    if (wrap instanceof HTMLElement && wrap.getAttribute("data-open") === "1") return;
    softSyncSettingsModel(wrap, label, cost, panel);
    if (wrap instanceof HTMLElement && dummyDriftedOffSettings(wrap, panel)) teardownDummySettingsUi();
  }

  function dummyDriftedOffSettings(wrap, panel) {
    if (!(wrap instanceof HTMLElement) || !wrap.isConnected) return true;
    if (wrap.getAttribute("data-open") === "1" || dummyMenuHeld) return false;
    if (!(panel instanceof HTMLElement)) return true;
    const wr = wrap.getBoundingClientRect();
    const pr = panel.getBoundingClientRect();
    if (!wr.width || !pr.width) return true;
    if (wr.bottom < pr.top - 12 || wr.top > pr.bottom + 12) return true;
    if (wr.right < pr.left - 12 || wr.left > pr.right + 12) return true;
    return false;
  }

  function teardownDummySettingsUi() {
    settingsModelStablePanel = null;
    settingsModelKeepUntil = 0;
    try {
