        if (/add\s*clip/i.test(parentText)) break;
        if (parentText.length > 180) break;
        if (parent.getBoundingClientRect().height > 100) break;
        row = parent;
      }
      if (!(row instanceof HTMLElement)) return;
      if (/add\s*clip/i.test(normalize(row.innerText || row.getAttribute("aria-label") || ""))) return;
      row.setAttribute("data-flowdoverz-hide-extend", "1");
      row.style.setProperty("display", "none", "important");
      row.style.setProperty("visibility", "hidden", "important");
      row.style.setProperty("pointer-events", "none", "important");
      row.setAttribute("aria-hidden", "true");
    });
  }

