  /**
   * Jin Tools queueDeduction — queue a fake-credit deduct after generate starts.
   * Completes when a progress % appears, or after a short timeout.
   */
  function queueDeduction() {
    if (!ready || !portalConnected) return;
    if (isLockedBySubmission) return;
    const cost = Number(CREDIT_MAP[fakeModelName || selectedModel] || CREDIT_MAP[DEFAULT_MODEL] || 5);
    if (cost <= 0) return;
    pendingDeductCost = cost;
    isWaitingForPercentage = true;
    isLockedBySubmission = true;
    isGenerating = true;
    waitStartTime = Date.now();
    lastActionTime = waitStartTime;
  }

  function tickQueuedDeduction() {
    if (!isWaitingForPercentage) return;
    const now = Date.now();
    let sawPercent = false;
    document.querySelectorAll("span, div, p").forEach((el) => {
      if (!(el instanceof HTMLElement) || sawPercent) return;
      const t = normalize(el.innerText || el.textContent || "");
      if (t.length < 2 || t.length > 12) return;
      if (/^\d{1,3}\s*%$/.test(t)) sawPercent = true;
    });
    const timedOut = now - waitStartTime > 8000;
    if (!sawPercent && !timedOut) return;
    if (now - lastDeductTime < DEDUCT_COOLDOWN_MS && now - lastDeductAt < DEDUCT_COOLDOWN_MS) {
      isWaitingForPercentage = false;
      isLockedBySubmission = false;
      isGenerating = false;
      pendingDeductCost = 0;
      return;
    }
    const cost = pendingDeductCost || pendingCost();
    lastDeductTime = now;
    lastDeductAt = now;
    fakeBalance = Math.max(0, fakeBalance - cost);
    pendingDeductCost = 0;
    isWaitingForPercentage = false;
    isLockedBySubmission = false;
    isGenerating = false;
    persist();
    schedulePaint(true);
  }

