  function isSettingsChipText(text) {
    const t = normalize(text);
    if (!t || t.length > 80) return false;
    if (!/\bvideo\b/i.test(t)) return false;
    if (!/\b(4|6|8)\s*s\b/i.test(t)) return false;
    if (/ingredients|frames|generating\s*will\s*use|describe\s*your|get\s*ai\s*credits|9\s*:\s*16|16\s*:\s*9/i.test(t)) {
      return false;
    }
    const hasX1 = /\bx\s*1\b/i.test(t) || /\bx1\b/i.test(t);
    const compact = t.length <= 36;
    return hasX1 || compact;
  }

  function findSettingsChipFromTarget(target) {
    let node = target instanceof Element ? target : null;
    for (let depth = 0; node && depth < 8; depth += 1) {
      if (node instanceof HTMLElement) {
        if (node.closest("#flowdoverz-settings-panel, #flowdoverz-settings-backdrop")) return null;
        const text = normalize(node.innerText || node.textContent || "");
        if (isSettingsChipText(text)) {
          const rect = node.getBoundingClientRect();
          if (rect.width >= 90 && rect.width <= 460 && rect.height >= 22 && rect.height <= 64) {
            return node.closest("button, [role='button'], [role='combobox']") || node;
          }
        }
      }
      node = node.parentElement;
    }
    return null;
  }

  function isNativeSettingsPanel(el) {
    if (!(el instanceof HTMLElement)) return false;
    if (el.id === "flowdoverz-settings-panel" || el.closest("#flowdoverz-settings-panel")) return false;
    const text = normalize(el.innerText || "");
    if (!text || text.length < 20 || text.length > 900) return false;
    const hasModes = /\bimage\b/i.test(text) && /\bvideo\b/i.test(text);
    const hasMode2 = /\bframes\b/i.test(text) && /\bingredients\b/i.test(text);
    const hasAspect = /\b9\s*:\s*16\b/.test(text) && /\b16\s*:\s*9\b/.test(text);
    const hasDuration = /\b4\s*s\b/i.test(text) && /\b8\s*s\b/i.test(text);
    if (!(hasModes && hasMode2 && (hasAspect || hasDuration))) return false;
    const rect = el.getBoundingClientRect();
    if (rect.width < 200 || rect.width > 520 || rect.height < 180) return false;
    return true;
  }

  function suppressNativeSettingsPanels() {
    // Never hide Google's real settings — Jin paints on top of it.
    document.querySelectorAll("[data-flowdoverz-hide-native-settings]").forEach((el) => {
      el.removeAttribute("data-flowdoverz-hide-native-settings");
    });
  }

  function closeFakeModelMenus() {
    closeDummyModelMenu();
    document.querySelectorAll("#flowdoverz-settings-panel .fd-sp-model-wrap[data-open='1']").forEach((wrap) => {
      wrap.removeAttribute("data-open");
    });
