  function syncFakeSettingsPanel() {
    const panel = document.getElementById("flowdoverz-settings-panel");
    if (!(panel instanceof HTMLElement)) return;
    const model = selectedModel || DEFAULT_MODEL;
    panel.querySelectorAll(".fd-sp-model-label").forEach((el) => {
      el.textContent = model;
    });
    panel.querySelectorAll(".fd-sp-model-menu button[data-flowdoverz-model]").forEach((btn) => {
      if (!(btn instanceof HTMLElement)) return;
      const id = btn.getAttribute("data-flowdoverz-model") || "";
      if (id === model) btn.setAttribute("data-active", "true");
      else btn.removeAttribute("data-active");
    });
    panel.querySelectorAll(".fd-sp-aspect button[data-aspect]").forEach((btn) => {
      if (!(btn instanceof HTMLElement)) return;
      if (btn.getAttribute("data-aspect") === preferredAspect) btn.setAttribute("data-active", "true");
      else btn.removeAttribute("data-active");
    });
    panel.querySelectorAll(".fd-sp-duration button[data-duration]").forEach((btn) => {
      if (!(btn instanceof HTMLElement)) return;
      if (Number(btn.getAttribute("data-duration")) === preferredDuration) {
        btn.setAttribute("data-active", "true");
      } else {
        btn.removeAttribute("data-active");
      }
    });
    const cost = panel.querySelector(".fd-sp-cost");
    if (cost) cost.textContent = `Generating will use ${formatBalance(pendingCost())} credits`;
  }

  function positionFakeSettingsPanel(panel) {
    const rect = settingsAnchorRect;
    const width = Math.min(320, window.innerWidth - 24);
    panel.style.width = `${width}px`;
    // Force layout so we know the real height before placing.
    const height = Math.max(panel.getBoundingClientRect().height || 480, 360);
    let left = 12;
    let top = 72;
    if (rect) {
      left = Math.round(rect.left + rect.width / 2 - width / 2);
      const above = Math.round(rect.top - height - 10);
      const below = Math.round(rect.bottom + 10);
      top = above >= 12 ? above : below;
    }
    left = Math.max(12, Math.min(left, window.innerWidth - width - 12));
    top = Math.max(12, Math.min(top, window.innerHeight - Math.min(height, window.innerHeight - 24)));
    panel.style.left = `${left}px`;
    panel.style.top = `${top}px`;
  }

  function buildModelWrap(variant) {
    const wrap = document.createElement("div");
    wrap.className = "fd-sp-model-wrap";
    wrap.setAttribute("data-variant", variant);

    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "fd-sp-model-btn";
    btn.innerHTML =
      `<span class="fd-sp-model-label"></span>` +
      (variant === "bottom" ? modelSelectCaretSvg() : modelSelectChevronSvg());
    btn.addEventListener(
      "click",
      (event) => {
        event.preventDefault();
        event.stopPropagation();
        const open = wrap.getAttribute("data-open") === "1";
        closeFakeModelMenus();
        if (!open) wrap.setAttribute("data-open", "1");
      },
      true
    );

    const menu = document.createElement("div");
    menu.className = "fd-sp-model-menu";
    menu.setAttribute("role", "listbox");
    MODEL_SELECT_OPTIONS.forEach((name) => {
      const item = document.createElement("button");
      item.type = "button";
      item.setAttribute("role", "option");
      item.setAttribute("data-flowdoverz-model", name);
      item.innerHTML = `${modelSelectSpeakerSvg()}<span>${name}</span>`;
      item.addEventListener(
        "click",
        (event) => {
          event.preventDefault();
          event.stopPropagation();
          setSelectedModel(name);
          signalForceLowerPriority();
          closeFakeModelMenus();
          syncFakeSettingsPanel();
          showSelectedModelOnTrigger();
          persist();
          publishSelectedModel();
          schedulePaint(true);
        },
        true
      );
      menu.appendChild(item);
    });

    wrap.appendChild(btn);
    wrap.appendChild(menu);
    return wrap;
  }

