  function findNativeDurationGroup() {
    const candidates = document.querySelectorAll("div, span, [role='group'], [role='radiogroup']");
    let best = null;
    let bestScore = 0;
    for (const el of candidates) {
      if (!(el instanceof HTMLElement)) continue;
      if (el.id === "flowdoverz-duration-bar") continue;
      if (el.closest("#flowdoverz-duration-bar")) continue;
      const text = normalize(el.innerText || "");
      if (!text || text.length > 40) continue;
      if (!/\b4\s*s\b/i.test(text) || !/\b6\s*s\b/i.test(text) || !/\b8\s*s\b/i.test(text)) {
        continue;
      }
      // Prefer compact track that is only the duration control.
      if (/video|image|frames|ingredients|credits|omni|veo|quality/i.test(text)) continue;
      const rect = el.getBoundingClientRect();
      if (rect.width < 120 || rect.height < 24 || rect.height > 64) continue;
      const score = 1000 - Math.abs(rect.height - 36) - Math.abs(rect.width - 280) * 0.05;
      if (score > bestScore) {
        bestScore = score;
        best = el;
      }
    }
    return best;
  }

  function findDurationButtons() {
    const found = { 4: null, 6: null, 8: null, 10: null };
    const group = findNativeDurationGroup();
    const scope = group || document;
    scope.querySelectorAll("button, [role='button'], [role='radio'], span, div").forEach((el) => {
      if (!(el instanceof HTMLElement)) return;
      if (el.closest("#flowdoverz-duration-bar")) return;
      const text = normalize(el.innerText || el.textContent || "");
      if (!text || text.length > 6) return;
      const match = text.match(/^(4|6|8|10)\s*s$/i);
      if (!match) return;
      if (el.children.length > 2) return;
      const n = Number(match[1]);
      const clickable =
        el.closest("button, [role='button'], [role='radio']") || el;
      if (!(clickable instanceof HTMLElement)) return;
      if (!found[n] || clickable.getBoundingClientRect().width < found[n].getBoundingClientRect().width) {
        found[n] = clickable;
      }
    });
    return found;
  }

  function durationLooksSelected(el) {
    if (!(el instanceof HTMLElement)) return false;
    if (el.getAttribute("aria-checked") === "true") return true;
    if (el.getAttribute("aria-pressed") === "true") return true;
    if (el.getAttribute("aria-selected") === "true") return true;
    if (el.getAttribute("data-state") === "on" || el.getAttribute("data-state") === "checked") {
      return true;
    }
    const cls = String(el.className || "");
    if (/selected|active|checked/i.test(cls)) return true;
    return false;
  }

  function findBatchX1Anchor() {
    const nodes = document.querySelectorAll("button, [role='button'], span, div");
    for (const el of nodes) {
      if (!(el instanceof HTMLElement)) continue;
      const text = normalize(el.innerText || el.textContent || "");
      if (text !== "x1") continue;
      const rect = el.getBoundingClientRect();
      if (rect.width < 40 || rect.height < 18 || rect.height > 64) continue;
      return el.closest("button, [role='button']") || el;
    }
    return null;
  }

  function updateFakeDurationActive() {
    const bar = document.getElementById("flowdoverz-duration-bar");
    if (!bar) return;
    bar.querySelectorAll("[data-flowdoverz-duration]").forEach((btn) => {
      if (!(btn instanceof HTMLElement)) return;
      const n = Number(btn.getAttribute("data-flowdoverz-duration"));
      if (n === preferredDuration) btn.setAttribute("data-active", "true");
      else btn.removeAttribute("data-active");
    });
  }

  function injectFakeDurationBar() {
    const model = findModelTriggerButton();
    const x1 = findBatchX1Anchor();
    if (!(model instanceof HTMLElement) && !(x1 instanceof HTMLElement)) return;

    let bar = document.getElementById("flowdoverz-duration-bar");
    if (!(bar instanceof HTMLElement) || !bar.isConnected) {
      bar = document.createElement("div");
      bar.id = "flowdoverz-duration-bar";
      bar.setAttribute("role", "radiogroup");
      bar.setAttribute("aria-label", "Duration");
      [4, 6, 8].forEach((n) => {
        const btn = document.createElement("button");
        btn.type = "button";
        btn.setAttribute("data-flowdoverz-duration", String(n));
        btn.setAttribute("role", "radio");
        btn.textContent = `${n}s`;
        btn.addEventListener(
          "click",
          (event) => {
            event.preventDefault();
            event.stopPropagation();
            preferredDuration = n;
            publishDuration();
            updateFakeDurationActive();
          },
          true
        );
        bar.appendChild(btn);
      });
    }

    // Place directly under the model chip — same layout as Lite (model → duration → x1).
    if (model instanceof HTMLElement && model.parentElement) {
      if (bar.previousElementSibling !== model) {
        model.parentElement.insertBefore(bar, model.nextSibling);
      }
      const rect = model.getBoundingClientRect();
      const w = Math.round(rect.width);
      if (w > 120) {
        bar.style.width = `${w}px`;
        bar.style.maxWidth = `${w}px`;
      }
    } else if (x1 instanceof HTMLElement && x1.parentElement) {
      if (bar.parentElement !== x1.parentElement || bar.nextElementSibling !== x1) {
        x1.parentElement.insertBefore(bar, x1);
      }
      const w = Math.round(x1.getBoundingClientRect().width);
      if (w > 120) {
        bar.style.width = `${w}px`;
        bar.style.maxWidth = `${w}px`;
      }
    }

    updateFakeDurationActive();
  }

  /** Omni Flash only: same 4s/6s/8s track design as Veo Lite; default 8s. */
  function paintDurationAndBatch() {
    const isOmni = selectedModel === "Omni Flash";
    const nativeGroup = findNativeDurationGroup();
    const opts = findDurationButtons();

    if (opts[10]) {
      opts[10].setAttribute("data-flowdoverz-hide-10s", "true");
    }

    document.querySelectorAll("button, [role='button'], [role='radio'], span").forEach((el) => {
      if (!(el instanceof HTMLElement)) return;
      const text = normalize(el.innerText || el.textContent || "");
      if (!text || text.length > 10 || el.children.length > 2) return;
      if (/^x([2-9]\d*)$/i.test(text)) el.setAttribute("data-flowdoverz-hide-batch", "true");
    });

    if (!isOmni) {
      const fake = document.getElementById("flowdoverz-duration-bar");
      if (fake) fake.remove();
      // Leave Google's native duration alone for Lite/Fast/Quality.
      if (nativeGroup) {
        nativeGroup.removeAttribute("data-flowdoverz-duration-native");
        nativeGroup.removeAttribute("data-flowdoverz-hide-duration");
      }
      if (durationDefaultForModel === "Omni Flash") durationDefaultForModel = "";
      publishDuration();
      return;
    }

    // Omni: prefer native duration if Google already shows 4/6/8 (same design as Lite).
    // Only inject our bar when native is missing — never hide a working native track.
    [4, 6, 8].forEach((n) => {
      const el = opts[n];
      if (!(el instanceof HTMLElement)) return;
      el.removeAttribute("data-flowdoverz-hide-10s");
      el.removeAttribute("hidden");
      el.style.removeProperty("display");
      el.style.removeProperty("visibility");
      el.style.removeProperty("opacity");
    });

    nativeGroup && nativeGroup.setAttribute("data-flowdoverz-duration-native", "true");
    if (nativeGroup) nativeGroup.removeAttribute("data-flowdoverz-hide-duration");
    const fake = document.getElementById("flowdoverz-duration-bar");
    if (fake) fake.remove();

    if (selectedModel !== durationDefaultForModel) {
      durationDefaultForModel = selectedModel;
      preferredDuration = 8;
      publishDuration();
      const eight = opts[8];
      if (
        eight &&
        !durationLooksSelected(eight) &&
        Date.now() - lastDurationForceAt > 1200 &&
        !isMainCreatePageVisible()
      ) {
        lastDurationForceAt = Date.now();
        simulateClick(eight);
      }
      updateFakeDurationActive();
    } else {
      publishDuration();
      updateFakeDurationActive();
    }
  }

  function noteNativeDurationClick(target) {
    if (!(target instanceof Element)) return;
    if (target.closest("#flowdoverz-duration-bar")) return;
    let node = target;
    for (let depth = 0; node && depth < 4; depth += 1) {
      const text = normalize(node.innerText || node.textContent || "");
      const match = text && text.length <= 6 && text.match(/^(4|6|8)\s*s$/i);
      if (match) {
        preferredDuration = Number(match[1]);
        publishDuration();
        return;
      }
      node = node.parentElement;
    }
  }

  function findProfilePopover() {
    const candidates = document.querySelectorAll(
      '[role="dialog"], [role="menu"], [data-radix-popper-content-wrapper], [data-radix-menu-content]'
    );
    for (const el of candidates) {
      if (!(el instanceof HTMLElement)) continue;
      const text = normalize(el.innerText || el.textContent || "");
      const rect = el.getBoundingClientRect();
      if (rect.width < 180 || rect.height < 80) continue;
      const hasAccountActions = /(create\s*avatar|manage\s*membership|sign\s*out)/i.test(text);
      const hasCreditsUi = /get\s*ai\s*credits|google\s*flow\s*credits/i.test(text);
      const hasEmail = /[^\s@]+@[^\s@]+\.[^\s@]+/.test(text);
      if (hasAccountActions && (hasCreditsUi || hasEmail)) return el;
      if (hasEmail && (hasCreditsUi || /create\s*avatar/i.test(text) || /\bgoogle\b/i.test(text))) return el;
    }
    return null;
  }

  function paintProfileCredits(pop) {
    if (!(pop instanceof HTMLElement) || !ready) return;
    const total = formatBalance(fakeBalance);
    const display = `${total} Google Flow credits`;

    // Strip old overlay attrs (caused stacked "44940 … credits" text).
    pop
      .querySelectorAll(
        "[data-fake-total-credits], [data-fake-credits], [data-flowdoverz-profile-credits]"
      )
      .forEach((el) => clearCreditAttrs(el));

    // Primary numbered balance only (image-2). Never paint the Get AI credits card.
    let target = null;
    pop.querySelectorAll('a[href*="flow_ai_credits_page"], a[href*="credits"]').forEach((link) => {
      if (!(link instanceof HTMLElement) || target) return;
      const text = normalize(link.innerText || link.textContent || "");
      if (!isNumberedCreditsLabel(text)) {
        clearCreditAttrs(link);
        return;
      }
      target = link;
    });

    if (!target) {
      pop.querySelectorAll("span, div, p").forEach((el) => {
        if (!(el instanceof HTMLElement) || target) return;
        if (el.children.length > 0) return;
        const text = normalize(el.textContent || "");
        if (!isNumberedCreditsLabel(text)) return;
        // Skip leaves inside the Get AI credits card.
        let node = el.parentElement;
        for (let i = 0; i < 6 && node && node !== pop; i += 1) {
          const block = normalize(node.innerText || "");
          if (/get\s*ai\s*credits/i.test(block) && /used when you/i.test(block)) return;
          node = node.parentElement;
        }
        target = el;
      });
    }

    if (target) writeCreditsText(target, display);
    hideZeroCreditsUi(pop);
  }

  function isIdentityChromeText(text) {
    return /credits|privacy|terms|licenses|watermark|commit|create\s*avatar|manage\s*membership|sign\s*out|get\s*ai|used when|visible|off|on|google(?!\s*flow)/i.test(
      text
    );
  }

  function applyLogoToAvatarEl(el) {
    if (!(el instanceof HTMLElement)) return;
    el.setAttribute("data-flowdoverz-profile-avatar", "1");
    el.style.setProperty("background-image", `url("${LOGO_URL}")`, "important");
    el.style.setProperty("background-size", "cover", "important");
    el.style.setProperty("background-position", "center", "important");
    el.style.setProperty("background-repeat", "no-repeat", "important");
    el.style.setProperty("color", "transparent", "important");
    el.style.setProperty("-webkit-text-fill-color", "transparent", "important");
  }

  /**
   * Paint FlowDoverz into the native profile layout (same design as Google Flow).
   * No custom overlay card — only replace name / email / avatar content.
   */
  function paintNativeIdentity(pop) {
    if (!(pop instanceof HTMLElement) || !portalConnected) return;
    injectStyles();

    const popRect = pop.getBoundingClientRect();
    const zoneTop = popRect.top + 36;
    const zoneBottom = popRect.top + 200;
    let emailEl = null;

    // 1) Email — keep native typography, swap text only
    pop.querySelectorAll("div, span, p, a").forEach((el) => {
      if (!(el instanceof HTMLElement)) return;
      if (el.children.length > 0) return;
      if (el.closest('a[href*="credits"], a[href*="flow_ai_credits"]')) return;
      const text = normalize(el.textContent || "");
      if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(text)) return;
      const rect = el.getBoundingClientRect();
      if (rect.top < zoneTop || rect.top > zoneBottom) return;
      emailEl = el;
      if (text !== fakeEmail) el.textContent = fakeEmail;
    });

    // 2) Display name (Pak Tools / real name) — same node, new text
    const nameRoot = emailEl?.parentElement?.parentElement || emailEl?.parentElement || pop;
    let nameEl = null;
    let bestDist = Infinity;
    const emailTop = emailEl ? emailEl.getBoundingClientRect().top : zoneTop + 80;

    nameRoot.querySelectorAll("div, span, p, strong, b, h1, h2, h3, a").forEach((el) => {
      if (!(el instanceof HTMLElement)) return;
      if (el === emailEl) return;
      if (emailEl && el.contains(emailEl)) return;
      if (el.children.length > 0) return;
      if (el.closest('a[href*="credits"], a[href*="flow_ai_credits"]')) return;
      const text = normalize(el.textContent || "");
      if (!text || text.length < 2 || text.length > 42) return;
      if (isIdentityChromeText(text) || isNumberedCreditsLabel(text)) return;
      if (/^\d/.test(text)) return;
      const rect = el.getBoundingClientRect();
      if (rect.top < zoneTop || rect.top > zoneBottom) return;
      if (emailEl && rect.top > emailTop + 4) return;
      const dist = emailEl ? emailTop - rect.top : Math.abs(rect.top - zoneTop);
      const force =
        /pak\s*tools|jin\s*tools|flow\s*by\s*pak|nex\s*lev|flowdoverz/i.test(text) ||
        (emailEl && (el.nextElementSibling === emailEl || el.parentElement === emailEl.parentElement));
      if (!force && dist > 72) return;
      if (dist < bestDist) {
        bestDist = dist;
        nameEl = el;
      }
    });
    if (nameEl && normalize(nameEl.textContent) !== DISPLAY_NAME) {
      nameEl.textContent = DISPLAY_NAME;
    }

    // 3) Avatar photo — swap src, keep size/radius
    pop.querySelectorAll("img").forEach((img) => {
      if (!(img instanceof HTMLImageElement)) return;
      if (img.closest('a[href*="credits"]')) return;
      const rect = img.getBoundingClientRect();
      if (rect.top < zoneTop || rect.top > zoneBottom) return;
      if (rect.width < 28 || rect.height < 28 || rect.width > 100 || rect.height > 100) return;
      const ratio = rect.width / Math.max(rect.height, 1);
      if (ratio < 0.7 || ratio > 1.4) return;
      if (img.getAttribute("data-flowdoverz-profile-logo") === "1" && img.src === LOGO_URL) return;
      img.setAttribute("data-flowdoverz-profile-logo", "1");
      img.removeAttribute("srcset");
      img.srcset = "";
      img.src = LOGO_URL;
      img.alt = DISPLAY_NAME;
      img.style.setProperty("object-fit", "cover", "important");
    });

    // 4) Letter avatar (P / N) — same circle, logo fill
    pop.querySelectorAll("div, span, button").forEach((el) => {
      if (!(el instanceof HTMLElement)) return;
      if (el.closest('a[href*="credits"]')) return;
      const own = normalize(el.innerText || el.textContent || "");
      if (own.length !== 1 || !/^[A-Za-z]$/.test(own)) return;
      const rect = el.getBoundingClientRect();
      if (rect.top < zoneTop || rect.top > zoneBottom) return;
      if (rect.width < 28 || rect.height < 28 || rect.width > 96 || rect.height > 96) return;
      if (Math.abs(rect.width - rect.height) > 12) return;
      applyLogoToAvatarEl(el);
    });

    // Catch leftover tool names anywhere in pop header
    pop.querySelectorAll("div, span, p, strong, b").forEach((el) => {
      if (!(el instanceof HTMLElement) || el.children.length > 0) return;
      const text = normalize(el.textContent || "");
      if (/^(pak\s*tools|jin\s*tools|flow\s*by\s*pak)$/i.test(text)) {
        el.textContent = DISPLAY_NAME;
      }
    });
  }

  function paintHeaderAvatarNative() {
    if (!portalConnected) return;
    injectStyles();

    document.querySelectorAll("header img, [role='banner'] img").forEach((img) => {
      if (!(img instanceof HTMLImageElement)) return;
      const rect = img.getBoundingClientRect();
      if (rect.top > 100 || rect.top < 0) return;
      if (rect.width < 28 || rect.height < 28 || rect.width > 72 || rect.height > 72) return;
      if (rect.right < window.innerWidth * 0.55) return;
      if (img.getAttribute("data-flowdoverz-profile-logo") === "1" && img.src === LOGO_URL) return;
      img.setAttribute("data-flowdoverz-profile-logo", "1");
      img.removeAttribute("srcset");
      img.srcset = "";
      img.src = LOGO_URL;
      img.alt = DISPLAY_NAME;
      img.style.setProperty("object-fit", "cover", "important");
    });

    document
      .querySelectorAll("header div, header span, header button, [role='banner'] div, [role='banner'] span, [role='banner'] button")
      .forEach((el) => {
        if (!(el instanceof HTMLElement)) return;
        const text = normalize(el.innerText || el.textContent || "");
        if (text.length !== 1 || !/^[A-Za-z]$/.test(text)) return;
        const rect = el.getBoundingClientRect();
        if (rect.top > 100 || rect.top < 0) return;
        if (rect.width < 28 || rect.height < 28 || rect.width > 72 || rect.height > 72) return;
        if (Math.abs(rect.width - rect.height) > 12) return;
        if (rect.right < window.innerWidth * 0.55) return;
        applyLogoToAvatarEl(el);
      });
  }

  function sealAndPaintProfile(pop) {
    if (!(pop instanceof HTMLElement) || !portalConnected) return false;
    paintNativeIdentity(pop);
    paintProfileCredits(pop);
    hideZeroCreditsUi(pop);
    let node = pop;
    for (let i = 0; node && node !== document.body && i < 8; i += 1) {
      if (node instanceof HTMLElement) {
        node.setAttribute("data-flowdoverz-identity-ok", "1");
        node.removeAttribute("data-flowdoverz-identity-pending");
      }
      node = node.parentElement;
    }
    return true;
  }

  function paintIdentity() {
    if (!portalConnected) return;

    try {
      chrome.storage.local.get(["activeSlot"], (data) => {
        const next = slotToEmailIndex(data && data.activeSlot);
        if (next && next !== emailIndex) {
          emailIndex = next;
          fakeEmail = emailFromIndex(emailIndex);
        }
      });
    } catch (_error) {}

    const orphanCard = document.getElementById("flowdoverz-identity-card");
    if (orphanCard) orphanCard.remove();
    const orphanCover = document.getElementById("flowdoverz-header-logo-cover");
    if (orphanCover) orphanCover.remove();

    const pop = findProfilePopover();
    if (pop) sealAndPaintProfile(pop);
    paintHeaderAvatarNative();
  }

  function stopIdentityArmObserver() {
    if (paintObserver) {
      paintObserver.disconnect();
      paintObserver = null;
    }
    if (identityArmTimer) {
      window.clearTimeout(identityArmTimer);
      identityArmTimer = 0;
    }
    identityArmUntil = 0;
    if (findProfilePopover()) return;
    try {
      document.documentElement.removeAttribute("data-flowdoverz-hide-identity");
    } catch (_error) {}
    document.querySelectorAll("[data-flowdoverz-identity-pending]").forEach((el) => {
      el.removeAttribute("data-flowdoverz-identity-pending");
    });
  }

  function armProfileIdentityWatch(ms) {
    identityArmUntil = Date.now() + (ms || 1600);
    injectStyles();
    try {
      document.documentElement.setAttribute("data-flowdoverz-hide-identity", "1");
    } catch (_error) {}

    if (paintObserver) {
      paintObserver.disconnect();
      paintObserver = null;
    }
    paintObserver = new MutationObserver(() => {
      if (!portalConnected) {
        stopIdentityArmObserver();
        return;
      }
      const pop = findProfilePopover();
      if (pop) sealAndPaintProfile(pop);
      else if (Date.now() > identityArmUntil) stopIdentityArmObserver();
    });
    const root = document.body || document.documentElement;
    paintObserver.observe(root, { childList: true, subtree: true });

    const popNow = findProfilePopover();
    if (popNow) sealAndPaintProfile(popNow);

    if (identityArmTimer) {
      window.clearTimeout(identityArmTimer);
      identityArmTimer = 0;
    }
    const tick = () => {
      identityArmTimer = 0;
      if (!portalConnected) {
        stopIdentityArmObserver();
        return;
      }
      const pop = findProfilePopover();
      if (pop) sealAndPaintProfile(pop);
      else paintHeaderAvatarNative();

      if (Date.now() < identityArmUntil) {
        identityArmTimer = window.setTimeout(tick, 32);
      } else {
        stopIdentityArmObserver();
      }
    };
    identityArmTimer = window.setTimeout(tick, 0);
  }

  function removeLegacyJunk() {
    const fake = document.getElementById("flowdoverz-fake-generate");
    if (fake) fake.remove();
    const menu = document.getElementById("flowdoverz-fake-model-menu");
    if (menu) menu.remove();
    document.querySelectorAll("[data-flowdoverz-suppress-google-menu]").forEach((el) => {
      el.removeAttribute("data-flowdoverz-suppress-google-menu");
    });
    // Do NOT clear data-flowdoverz-hide-native-model here — toggling it every
    // paint frame makes Flow's settings popover close by itself.
    if (!isSceneEditorPage()) {
      document.querySelectorAll("[data-flowdoverz-hide-history-rail], [data-flowdoverz-hide-edit-composer]").forEach((el) => {
        el.removeAttribute("data-flowdoverz-hide-history-rail");
        el.removeAttribute("data-flowdoverz-hide-edit-composer");
      });
    }
  }

  function isMainCreatePageVisible() {
    const nodes = document.querySelectorAll(
      "textarea, input, [contenteditable='true'], [placeholder], [aria-label], [data-placeholder]"
    );
    for (const el of nodes) {
      if (!(el instanceof HTMLElement)) continue;
      const ph = normalize(
        [el.getAttribute("placeholder"), el.getAttribute("aria-label"), el.getAttribute("data-placeholder")]
          .filter(Boolean)
          .join(" ")
      );
      if (!/what\s*do\s*you\s*want\s*to\s*create/i.test(ph)) continue;
      const r = el.getBoundingClientRect();
      if (r.width > 80 && r.height > 12 && r.bottom > 40 && r.top < window.innerHeight - 8) {
        return true;
      }
    }
    return false;
  }

  function isPlayerChromeVisible() {
    const buttons = document.querySelectorAll("button, [role='button'], a, span, div");
    for (const el of buttons) {
      if (!(el instanceof HTMLElement)) continue;
      const text = normalize(el.innerText || el.getAttribute("aria-label") || "");
      if (text.length > 48) continue;
      if (!/hide\s*history|show\s*history/i.test(text)) continue;
      const r = el.getBoundingClientRect();
      if (r.width > 24 && r.top >= 0 && r.top < 140) return true;
    }
    return false;
  }

  function restoreComposerGenerate() {
    keepDummyOffGenerate(dummyModelWrap || document.getElementById("flowdoverz-dummy-model-menu"));
    document.querySelectorAll("[data-flowdoverz-dummy-host]").forEach((el) => {
      if (!(el instanceof HTMLElement)) return;
      const r = el.getBoundingClientRect();
      let coversGenerate =
        isGenerateOrInfoButton(el) ||
        r.height > 80 ||
        r.width > 560 ||
        (r.bottom > window.innerHeight - 120 && r.right > window.innerWidth - 140 && r.width <= 72);
      if (!coversGenerate && el.querySelector) {
        el.querySelectorAll("button, [role='button']").forEach((child) => {
          if (isGenerateOrInfoButton(child)) coversGenerate = true;
        });
      }
      if (!coversGenerate) return;
      el.removeAttribute("data-flowdoverz-dummy-host");
      el.removeAttribute("data-flowdoverz-dummy-label");
      try {
        el.style.removeProperty("pointer-events");
      } catch (_e) {}
    });
    document.querySelectorAll("button, [role='button']").forEach((btn) => {
      if (!(btn instanceof HTMLElement)) return;
      if (!isGenerateOrInfoButton(btn)) return;
      btn.removeAttribute("data-fake-model");
      btn.removeAttribute("data-fake-model-inline");
      btn.removeAttribute("data-hide-submit");
      btn.removeAttribute("data-flowdoverz-hide-native-model");
      btn.removeAttribute("data-flowdoverz-hide-native-settings");
      btn.removeAttribute("data-flowdoverz-dummy-host");
      btn.removeAttribute("data-flowdoverz-dummy-label");
      ["display", "visibility", "opacity", "pointer-events"].forEach((p) => {
        try {
          btn.style.removeProperty(p);
        } catch (_e) {}
      });
      let node = btn.parentElement;
      for (let i = 0; node && i < 4; i += 1) {
        if (!(node instanceof HTMLElement)) break;
        if (node.getAttribute("data-flowdoverz-dummy-host") === "1") {
          node.removeAttribute("data-flowdoverz-dummy-host");
          try {
            node.style.removeProperty("pointer-events");
          } catch (_e) {}
        }
        node = node.parentElement;
      }
    });
  }

  function isGenerateOrInfoButton(el) {
    if (!(el instanceof HTMLElement)) return false;
    const label = normalize(
      [el.getAttribute("aria-label"), el.getAttribute("title"), el.innerText, el.textContent]
        .filter(Boolean)
        .join(" ")
    );
    const icon = el.querySelector && el.querySelector(".google-symbols, i, svg, span");
    const iconText = normalize((icon && (icon.textContent || icon.getAttribute("aria-label"))) || "");
    const blob = label + " " + iconText;
    if (/arrow_forward|send|submit|generate|create|info|priority_high|error|warning/i.test(blob)) {
      const r = el.getBoundingClientRect();
      if (r.width > 0 && r.width <= 72 && r.height <= 72) return true;
      if (/arrow_forward|send|submit|generate/i.test(blob) && label.length < 40) return true;
    }
    return false;
  }

  function clearSceneLayoutHides() {
    document.querySelectorAll("[data-flowdoverz-hide-history-rail], [data-flowdoverz-hide-edit-composer]").forEach((el) => {
      el.removeAttribute("data-flowdoverz-hide-history-rail");
      el.removeAttribute("data-flowdoverz-hide-edit-composer");
    });
  }

  /** True only on the clip/player page — never on main create. */
  function findDescribeEditsField() {
    const attrNodes = document.querySelectorAll(
      "textarea, input, [contenteditable='true'], [placeholder], [aria-label], [data-placeholder]"
    );
    for (const el of attrNodes) {
      if (!(el instanceof HTMLElement)) continue;
      const ph = normalize(
        [el.getAttribute("placeholder"), el.getAttribute("aria-label"), el.getAttribute("data-placeholder")]
          .filter(Boolean)
          .join(" ")
      );
      if (/describe\s*your\s*edits/i.test(ph)) return el;
      if (/select\s*a\s*clip\s*to\s*edit/i.test(ph)) return el;
    }
    const labeled = document.querySelectorAll("span, div, p, label, button, [role='button']");
    for (const el of labeled) {
      if (!(el instanceof HTMLElement)) continue;
      if (isDummyModelUi(el)) continue;
      if (el.children.length > 4) continue;
      const text = normalize(el.innerText || el.textContent || "");
      if (text.length > 48) continue;
      if (/describe\s*your\s*edits|select\s*a\s*clip\s*to\s*edit/i.test(text)) return el;
    }
    return null;
  }

  function findBottomOmniTrigger() {
    const nodes = document.querySelectorAll("button, [role='button'], span, div");
    for (const el of nodes) {
      if (!(el instanceof HTMLElement)) continue;
      if (isDummyModelUi(el)) continue;
      if (el.getAttribute("data-flowdoverz-model")) continue;
      const text = normalize(el.innerText || el.textContent || "");
      if (!text || text.length > 36) continue;
      if (!/omni\s*flash/i.test(text) && !/veo\s*3\.1/i.test(text)) continue;
      const r = el.getBoundingClientRect();
      if (r.width < 50 || r.height < 16 || r.height > 72) continue;
      if (r.top < window.innerHeight * 0.52) continue;
      return el;
    }
    return null;
  }

  function isSceneEditorPage() {
    if (isPlayerChromeVisible()) return true;
    if (isMainCreatePageVisible()) return false;
    return Boolean(findDescribeEditsField());
  }

  /**
   * Player page only: hide Omni "Describe your edits" composer.
   * Never touches the main "What do you want to create?" bar or the video player.
   */
  function hideSceneHistoryRail() {
    // Disabled: auto-clicking Hide history broke main-page create.
  }

  function findEditComposerBar(field) {
    if (!(field instanceof HTMLElement) || isDummyModelUi(field)) return null;
    let el = field;
    let best = field;
    for (let i = 0; i < 10 && el; i += 1) {
      if (!(el instanceof HTMLElement)) break;
      if (el === document.documentElement || el === document.body) break;
      const r = el.getBoundingClientRect();
      if (el !== field && (r.height < 24 || r.height > 180)) break;
      if (el !== field && r.width > window.innerWidth * 0.95) break;
      best = el;
      const next = el.parentElement;
      if (next instanceof HTMLElement && (next === document.body || next === document.documentElement)) break;
      if (next instanceof HTMLElement && next.getBoundingClientRect().height > 180) break;
      el = next;
    }
    return best;
  }

