  "use strict";

  const HEARTBEAT_TYPE = "FLOWBRIDGE_EXTENSION_HEARTBEAT";
  const DISCONNECTED_TYPE = "FLOWBRIDGE_EXTENSION_DISCONNECTED";
  const HEARTBEAT_ACTION = "FLOWBRIDGE_WATCHDOG_PING";
  let pingInFlight = false;
  let consecutiveFailures = 0;

  function signalDisconnected() {
    window.postMessage(
      {
        type: DISCONNECTED_TYPE,
        timestamp: Date.now(),
      },
      "*"
    );
  }

  function reportFailure() {
    consecutiveFailures += 1;
    // ~2s without the extension → force Flow logout (uninstall / disabled).
    if (consecutiveFailures < 8) return;
    signalDisconnected();
  }

  function sendHeartbeat() {
    if (pingInFlight) return;
    pingInFlight = true;

    try {
      chrome.runtime.sendMessage({ action: HEARTBEAT_ACTION }, (response) => {
        pingInFlight = false;

        if (chrome.runtime.lastError || !response) {
          reportFailure();
          return;
        }

        // Plan expired, tamper, or not connected → kill Flow session immediately.
        if (response.alive !== true || response.kill === true) {
          consecutiveFailures = 0;
          signalDisconnected();
          return;
        }

        consecutiveFailures = 0;
        window.postMessage(
          {
            type: HEARTBEAT_TYPE,
            timestamp: Date.now(),
          },
          "*"
        );
      });
    } catch (_error) {
      pingInFlight = false;
      reportFailure();
    }
  }

  chrome.runtime.onMessage.addListener((request) => {
    if (request && request.action === "FLOWBRIDGE_FORCE_LOGOUT") {
      signalDisconnected();
    }
  });

  sendHeartbeat();
  window.setInterval(sendHeartbeat, 250);
})();
(function () {
  "use strict";

  const HEARTBEAT_TYPE = "FLOWBRIDGE_EXTENSION_HEARTBEAT";
  const DISCONNECTED_TYPE = "FLOWBRIDGE_EXTENSION_DISCONNECTED";
  const SIGN_OUT_URL = "https://labs.google/fx/api/auth/signout";
  const FLOW_URL = "https://labs.google/fx/tools/flow";
  // If heartbeats stop (extension removed/disabled), logout within a few seconds.
  const HEARTBEAT_TIMEOUT_MS = 8000;

  let lastHeartbeat = 0;
  let armed = false;
  let logoutStarted = false;

  window.addEventListener("message", (event) => {
    if (event.source !== window || !event.data) return;

    if (event.data.type === DISCONNECTED_TYPE) {
      if (armed) forceFlowLogout();
      return;
    }

    if (event.data.type !== HEARTBEAT_TYPE) return;
    armed = true;
    lastHeartbeat = Date.now();
  });

  document.addEventListener("visibilitychange", () => {
    if (document.visibilityState === "visible" && armed) {
      lastHeartbeat = Date.now();
    }
  });

  window.addEventListener("pageshow", () => {
    if (armed) lastHeartbeat = Date.now();
  });

  window.addEventListener("focus", () => {
    if (armed) lastHeartbeat = Date.now();
  });

  function clearPageSession() {
    try {
      sessionStorage.clear();
    } catch (_error) {}

    try {
      localStorage.setItem("__flowdoverz_extension_disconnected__", "1");
    } catch (_error) {}

    try {
      for (const cookie of document.cookie.split(";")) {
        const separator = cookie.indexOf("=");
        const name = (separator >= 0 ? cookie.slice(0, separator) : cookie).trim();
        if (!name) continue;
        for (const domain of ["labs.google", ".labs.google", "google.com", ".google.com"]) {
          document.cookie = `${name}=; Max-Age=0; path=/; domain=${domain}; SameSite=Lax; Secure`;
        }
        document.cookie = `${name}=; Max-Age=0; path=/; SameSite=Lax; Secure`;
      }
    } catch (_error) {}
  }

  function readCsrfToken() {
    try {
      const csrfCookieNames = [
        "__Host-next-auth.csrf-token",
        "__Secure-next-auth.csrf-token",
        "next-auth.csrf-token",
      ];
      for (const part of document.cookie.split(";")) {
        const separator = part.indexOf("=");
        if (separator < 0) continue;
        const name = part.slice(0, separator).trim();
        if (!csrfCookieNames.includes(name)) continue;
        const value = decodeURIComponent(part.slice(separator + 1));
