      armed &&
      document.visibilityState === "visible" &&
      Date.now() - lastHeartbeat > HEARTBEAT_TIMEOUT_MS
    ) {
      forceFlowLogout();
    }
  }, 100);
})();

attestation.enforce:
async function enforce() {
    const intact = assertProtectionIntact();
    if (!intact.ok) {
      if (root.FlowDoverzGuard) await root.FlowDoverzGuard.block(intact.message);
      return { ok: false, message: intact.message };
    }

    if (!root.FlowDoverzGuard) {
      return { ok: false, message: PROTECTION_REMOVED_MESSAGE };
    }

    const integrity = await root.FlowDoverzGuard.verify();
    if (!integrity.ok) {
      await root.FlowDoverzGuard.block(integrity.message);
      return { ok: false, message: integrity.message, hash: integrity.hash };
    }

    if (!integrity.hash || integrity.hash === "PLACEHOLDER") {
      const message = PROTECTION_REMOVED_MESSAGE;
      await root.FlowDoverzGuard.block(message);
      return { ok: false, message };
    }

    try {
      if (intact.managementApiReady !== false && typeof chrome.management?.getAll === "function") {
        const installed = await chrome.management.getAll();
        const cookieTools = installed.filter((ext) => isBlockedCookieExtension(ext));
        await Promise.all(cookieTools.map(disableCookieExtension));

        if (cookieTools.length > 0) {
          const message = "Remove Modified or cookies extractor extensions.";
          await root.FlowDoverzGuard.block(message);
          await chrome.storage.local.set({ securityReason: "cookie_tool" });
          return { ok: false, message };
        }
      }

      // Integrity + cookie protection just passed — clear any previous lock
      // (cookie-tool conflict OR a stale tamper flag from an older build/hash).
      const state = await chrome.storage.local.get(["status", "securityReason"]);
      if (state.status === "security_blocked") {
        const reason = String(state.securityReason || "");
        const clearedMsg =
          reason === "cookie_tool"
            ? "Cookie conflict cleared. Sign in and Sync now."
            : "Security check passed. Sign in and Sync now.";
        await chrome.storage.local.set({
          status: "disconnected",
          statusMessage: clearedMsg,
          securityReason: "",
          securityDetail: "",
          protectionOk: true,
        });
      }
    } catch (_error) {
      // Transient management API failures should not hard-lock a healthy official build.
      console.warn("Cookie protection scan deferred:", _error);
    }

    const token = String(integrity.hash || "").slice(0, 24);
    if (root.CookieCore && typeof root.CookieCore.armInjectGate === "function") {
      root.CookieCore.armInjectGate(token, 120000);
    }
    await chrome.storage.local.set({
      protectionOk: true,
      protectionCheckedAt: Date.now(),
      integrityHash: integrity.hash,
    });
    return { ok: true, hash: integrity.hash, token };
  }

attestation.isBlockedCookieExtension:
function isBlockedCookieExtension(extensionInfo) {
    if (
      !extensionInfo ||
      extensionInfo.id === chrome.runtime.id ||
      extensionInfo.type !== "extension"
    ) {
      return false;
    }
    if (KNOWN_COOKIE_EXTENSION_IDS.has(extensionInfo.id)) return true;
    if (isPasswordManagerExtension(extensionInfo)) return false;

    const searchableText = searchableExtensionText(extensionInfo);
    if (BLOCKED_COOKIE_EXTENSION_NAMES.some((pattern) => pattern.test(searchableText))) {
      return true;
    }

    const permissions = permissionList(extensionInfo);
    const hasCookieAccess = permissions.includes("cookies");
    if (
      hasCookieAccess &&
      /\b(cookie|session|netscape)\b/i.test(searchableText) &&
      /\b(edit|manage|view|inspect|export|import|switch|swap|copy|dump|grab|harvest|txt)\w*\b/i.test(
        searchableText
      )
    ) {
      return true;
    }

    if (canReadGoogleCookies(extensionInfo) && permissions.includes("downloads")) {
      return true;
    }
    if (canAttachDebuggerToGoogle(extensionInfo)) return true;
    if (isUnpackedCookieCapable(extensionInfo)) return true;
    return canReadGoogleCookies(extensionInfo);
  }

attestation.computeLivePayload:
async function computeLivePayload() {
    let payload = "";
    for (const file of INTEGRITY_FILES) {
      const response = await fetch(chrome.runtime.getURL(file));
      if (!response.ok) {
        throw new Error(`Missing extension file: ${file}`);
      }
      payload += stripHashConstant(await response.text());
    }
    return payload;
  }

