async function proveForSync(portalUrl) {
    const stub = assertGuardNotStubbed();
    if (!stub.ok) {
      return { ok: false, message: stub.message };
    }
    const challenge = await fetchServerChallenge(portalUrl);
    if (!challenge) {
      return {
        ok: false,
        message:
          "Could not verify extension with server. Check your connection, then Sync again.",
      };
    }
    const latestVersion = String(challenge.latestVersion || challenge.version || "");
    if (isOlderVersion(extensionVersion(), latestVersion)) {
      return {
        ok: false,
        code: "EXTENSION_UPDATE_REQUIRED",
        message: challenge.updateMessage || UPDATE_REQUIRED_MESSAGE,
        latestVersion,
      };
    }
    try {
      const proved = await buildChallengeProof(challenge.nonce);
      if (
        !proved.hash ||
        proved.hash === "PLACEHOLDER" ||
        proved.hash !== EXPECTED_INTEGRITY_HASH ||
        !proved.proof
      ) {
        return { ok: false, message: challenge.tamperMessage || FALLBACK_TAMPER };
      }
      await chrome.storage.local.set({
        serverTamperMessage: challenge.tamperMessage,
        integrityChallenge: challenge.challenge,
        integrityNonce: challenge.nonce,
        integrityProof: proved.proof,
        integrityHash: proved.hash,
      });
      return {
        ok: true,
        hash: proved.hash,
        proof: proved.proof,
        challenge: challenge.challenge,
        nonce: challenge.nonce,
        message: challenge.tamperMessage,
      };
    } catch (_error) {
      return { ok: false, message: challenge.tamperMessage || FALLBACK_TAMPER };
    }
  }
